COLLDATA("tadabburur","ur",[[369,"§الشعراء\ndeeds\nکوئی دعوتی کام کیجئے اور اس میں آپ کو جو بھی تکلیف اور مشقت برداشت کرنی پڑے تو اسے فی سبیل اللہ شمار کیجئے.\nاللہ تعالیٰ سے دعا مانگئے کہ آپ کے گناہ بخش دے اور آپ کو ایمان پر ثابت قدم رکھے.\nاللہ تعالیٰ نے اس سورت میں جن جن مواقع پر موسیٰ علیہ السلام کی حفاظت،ان کی مدد اور تائید کا ذکر کیا ہے، وہ مقامات لکھئے.\nguid\nجو اللہ کے دین یعنی اسلام کے علاوہ میں عزت تلاش کریگااللہ اسے ذلیل کردیگا.\nظالموں کی دھمکیاں دنیا اور آخرت میں بلند درجات کے حصول کا ذریعہ ہوتی ہیں.\nبندے اللہ کی نافرمانی کریں تو وہ اللہ کی نظروں میں بہت حقیر ہوجاتے ہیں۔دیکھئے فرعون جیسا سرکش بادشاہ بھی جب ربوبیت کا دعویٰ کربیٹھا تو اسے سمندر میں ڈبودیاگیا.\nrefl\nقَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ ٤٣\nموسیٰ علیہ السلام نے میدان میں اپنی لاٹھی ڈالنے میں پہل نہیں کی کیونکہ یہاں علم کا مسئلہ تھا جنگ کا نہیں۔معرکہ میں نقصان دہ امورکو ختم کرکے جنگ میں پہل کی جاتی ہے لیکن علم کے میدان میں مد مقابل کی طرف سے پہل کرنا بہتر ہوتا ہے کیونکہ جب وہ اپنی تمام حجتوں کو سامنے لے آئیگاتو اس کی تمام حجتوں کو شواہد اور دلائل کی روشنی میں باطل کرنا آسان ہوجائیگااور حق ظاہر ہوکر باطل پر غالب ہوجائیگااور موسیٰ علیہ السلام نے یہ اسلوب بحکم الہی اختیار کیا تھا۔ (جزائری: ۳؍ ۶۴۹)\nموسیٰ علیہ السلام نے جادوگروں سے پہلے اپنی لاٹھی کیوں نہیں ڈالی؟\nفَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ ٤٤\n(وقالوا بعزة فرعون) یعنی انہوں نے فرعون کی عزت وجلال کی قسم کھاکر کہا۔تو جو بھی غیر اللہ کی قسم کھائے گا جیسے کہ کہے:فلاں کی زندگی کی قسم، فلاں کے سر کی قسم!اور اس قسم کی دوسری قسمیں۔تو گویا وہ اسی طرز جاہلیت کی پیروی میں ہے۔ (البقاعی: ۱۴؍ ۳۲-۳۳)\nغیر اللہ کی قسم کھانا اللہ کے ساتھ تعظیم میں اس ذات کو برابراور شریک ٹھہرانا ہے جس کی قسم کھائی جارہی ہے۔اس کی وضاحت کریں.\nفَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ ٤٤\nان لوگوں کا ارادہ تھا کہ اس سے موسیٰ علیہ السلام کے دل میں خوف پیدا ہوجائیگا تاکہ اپنی باری میں آپ بیزار نفسی سے لاٹھی ڈالیں۔کیونکہ انہیں یہ بات اچھی طرح معلوم تھی کہ پختہ ارادہ دراصل جادو کی کامیابی میں اور ناظرین پر اس کا اثر ڈالنے میں سب سے بڑا سبب ہے۔ (ابن عاشور: ۱۹؍۱۲۷)\nجادوگروں نے یہ کیوں کہا: (إنا لنحن الغالبون)“بے شک ہم ہی غالب رہیں گے”؟\nإِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ\nیہ ہٹ دھرمی ہے،اس کا باطل ہونا ہر ایک کو معلوم ہے کیونکہ اس سے پہلے یہ لوگ موسیٰ علیہ السلام کے ساتھ کبھی اکٹھا نہیں ہوئے تھے۔ پھر آپ ان جادوگروں کے بڑے استاد کیسے ہوسکتے تھے اور انہیں جادو کیسے سکھاسکتے تھے!اس طرح کی بات کوئی عقلمند نہیں کہہ سکتا۔ (ابن کثیر: ۳؍۳۲۴)\nآیت کریمہ فرعون کی بہت بڑی ہٹ دھرمی پر دلالت کرتی ہے۔اس کی وضاحت کریں.\nقَالُواْ لَا ضَيۡرَۖ\nجادوگروں نے جس وقت ایمان کی مٹھاس حاصل کرلی اور اس کی لذت چکھ لی تو کہا کہ ہمیں کوئی پرواہ نہیں ہے کہ تم ہمیں کیا دھمکی دے رہے ہو۔ (السعدی؍۵۹۲)\nفرعون کی دھمکی سے جادوگر متاثر کیوں نہیں ہوئے؟\nإِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ ٥١\nانہوں نے حرص ولالچ سے تعبیر کیا جس میں اس بات کی طرف اشارہ ہے کہ سعادت مندی کے تمام اسباب اللہ کی طرف سے ہوتے ہیں گویا ا ن کی طرف اصلاً کوئی سبب نہیں ہے۔ (البقاعی: ۱۴؍۳۶)\nمغفرت میں حرص ولالچ کی تعبیر کا کیافائدہ ہے؟\nوَإِنَّا لَجَمِيعٌ حَٰذِرُونَ ٥٦\nمطلب یہ ہے کہ خوف وحذر آپ کی عادت ہے لہذا امت کو بھی چاہئے کہ اس صفت میں آپ کے ساتھ رہے۔یعنی ہماری عادت ہے کہ حوادث کے وقت ہم چوکنا ہوجاتے ہیں اور جو اس کے نتیجہ میں برے انجام پیش آسکتے ہیں اس بات سے بھی۔اور یہ سیاست کا بہت اہم اصول ہے جسے فساد کے اسباب کو روکنا کہتے ہیں،گرچہ اس کا فسادتک پہنچنا کمزور ترین ہی کیوں نہ ہو۔ (ابن عاشور: ۱۹؍۱۳۱)\nآیت کریمہ سیاست کے ایک بہت بڑے اصول پر دلالت کرتی ہے۔اس کی وضاحت کریں.\nwords\nبِعِزَّةِ فِرعَونَقسم هے فرعون كے غلبه اور قوت كي.\nتَلقَفُجلدي سے نگل گئي.\nمَا يَأفِكُونَجو وه جھوٹ اورفراڈ گھڑتے هيں.\nلاَ ضَيرَكوئي ضرر والي بات نهيں.\nمُنقَلِبُونَپلٹنے والے.\nحَاشِرِينَشهروں سے لشكركو جمع كرنے والے.\nلَشِرذِمَةٌايك چھوٹي حقير سي جماعت."],[370,"§الشعراء\ndeeds\nغیر اللہ سے دعا اور اس کے لئے ذبح اور افراد ومعاشرے پر اس کے خطرناک اثرات کے موضوع پر انٹرنیٹ کی کسی سائٹ پر یا موبائل کی کسی ایپلی کیشن پر مضمون لکھئے اور انہیں بھیجئے جو اس سے فائدہ اٹھاسکیں.\nیہ دعا پڑھئے:“اَللّٰهُمَّ عَافِنِيْ فِيْ بَدَنِيْ اَللّٰهُمَّ عافِنِيْ فِيْ سَمْعِيْ اَللّٰهُمّ عَافِنِيْ فِيْ بَصَرِيْ لَا اِلٰهَ اِلَّا أَنْتَ”۔اے اللہ!میرے جسم میں عافیت دے، اے اللہ!میرے کانوں میں عافیت دے،اے اللہ!میری آنکھوں میں عافیت دے۔تیرے سوا کوئی معبود برحق نہیں.\nاپنے اوپر اللہ کی تین نعمتیں شمار کیجئے پھر ان پر اللہ کا شکر ادا کیجئے۔ کیونکہ یہ اللہ سے آپ کی محبت میں اضافہ کے اسباب میں سے ہے جیسے کہ ابراہیم علیہ السلام نے کہا تھا.\nguid\nتوجہ دیجئے کہ کس طرح اللہ تعالیٰ نے اکثر لوگوں کی حالت بیان کرتے ہوئے فرمایا ہے کہ وہ مومن نہیں ہیں،آپ اس پر غور کریں گے تو اپنے اوپر بھی گمراہی سے ڈریں گے چنانچہ بہ کثرت اللہ تعالیٰ سے ثبات قدمی کا سوال کیجئے.\nحرام تقلید سے محتاط رہئے جو پچھلی امتوں کے ہلاک ہونے کا سبب بن گئی،کیونکہ کافر اپنے آباء واجدادکی تقلید کی وجہ سے ہی اللہ تعالیٰ کے سیدھے راستہ سے گمراہ ہوگئے.\nیقین رکھئے کہ اگر آپ کو کوئی بھی بیماری لاحق ہو تو اللہ کے علاوہ اسے دور کرنے کی طاقت کسی میں بھی نہیں،انبیاء میں نہ اولیاء میں.\nrefl\nفَلَمَّا تَرَٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ ٦١ قَالَ كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ ٦٢\n(قال) موسیٰ علیہ السلام نے ان سے یہ بات دراصل ڈانٹنے کے لئے کہی کہ وہ کبھی ایسی بات نہ کہیں اور اس جانب رہنمائی کے لئے کہی کہ اللہ کی تدبیر کے آگے اس کی تدبیر کوئی فائدہ نہیں دیگی (كلا) ہر گز نہیں وہ تم لوگوں کو کبھی نہیں پاسکتے (إن معي ربي) بیشک میرے ساتھ میرا رب ہے جو حفاظت کریگا اور مدد کریگا۔(سيهدين) عنقریب وہ ایسی چیز کی طرف میری رہنمائی کریگا جس سے تمہیں ان سے نجات ملے گی اور تم ان پر غالب آجاؤگے۔ (الوسی: ۱۰؍۸۴)\nیقین کتنی عمدہ اور بہترین صفت ہے جس کے ذریعہ اللہ اپنے مومن بندے کو فتنوں کے وقت ثابت قدم رکھتا ہے۔آیتوں کی روشنی میں اس کی وضاحت کیجئے.\nوَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ ٦٩ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ ٧٠\n(واتل عليهم نبأ إبراهيم) یعنی اے محمد صلی اللہ علیہ وسلم! لوگوں کواس خصوصی صورت حال میں ابراہیم خلیل اللہ کی عظیم خبر بیان کردیں۔ ان کی خبریں اور کہانیاں درحقیقت بہت ہیں۔ لیکن ان کی سب سے بہترین اور دلچسپ کہانی وہ ہے جو ان کی رسالت اور قوم کی اللہ کی طرف دعوت اور ان کے ساتھ حجت و مباحثہ کرنا اور ان کے دعوؤں اور دلیلوں کو باطل کرنے سے متعلق ہے ہے اسی لئے ظرف (إذ)کے ساتھ اس خبر کو خاص کردیا اور فرمایا: (إذ قال لأبيه وقومه ما تعبدون) جب انہوں نے اپنے باپ اور اپنی قوم سے کہاکہ تم لوگ کس چیز کی عبادت کرتے ہو؟!(السعدی؍۵۹۲)\nاللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو حکم دیا کہ ابراہیم علیہ السلام کی تمام حالتوں کو چھوڑکر صرف دعوت الی اللہ کی حالت کی خبر دیں۔ایسا کیوں؟\nقَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ ٧٤\nانہوں نے اس بات سے اعراض کیا کہ بت کچھ سنتے یا نفع ونقصان پہنچاتے ہیں کیونکہ وہ مانتے تھے کہ وہ ایسا نہیں کر سکتے اور اعتراف کے علاوہ ان کے پاس انکار کی کوئی گنجائش نہیں ہے اور وہ مجبور ہوئے کہ تقلید کو اپنی سند ودلیل بنائیں۔گویا انہوں نے کہا کہ وہ نہ سنتے ہیں اور نہ ہی ہمیں نقصان ونفع پہنچاسکتے ہیں۔ہم نے اپنے باپ دادا کو ایسا ہی کرتے ہوئے پایا اور وہ ہماری ہی طرح ان کی پوجا کرتے تھے چنانچہ ہم نے ان کی پیروی کرلی۔ (الوسی: ۱۰؍۹۲)\nکیاقیامت کے دن غلطی میں باپ دادا کی تقلید حجت مانی جائیگی؟\nأَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ ٧٦\nان کے باپ دادا کی قدامت بیان کرکے ان کی تقلید میں حد درجہ بے اعتنائی و بے توجہی مقصود ہے کیونکہ قوموں کا یہ اصول رہا ہے کہ باپ دادا کا زمانہ جتنا ہی پرانا ہوتا ہے ان کی تقلید اتنی ہی ضروری ہوتی ہے۔ (ابن عاشور: ۱۹؍۱۴۱)\nباپ دادا کو قدامت سے کیوں متصف کیا گیا؟\nفَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ ٧٧\nکوئی شخص کہہ سکتا ہے کہ لکڑی،لوہے اور پیتل کو انسان کا دشمن کیسے کہا جاسکتا ہے؟تو اس کا مطلب یہ ہے کہ اگر تم ان کی عبادت کروگے تو قیامت کے دن وہ تمہارے دشمن ہوجائیں گے جیسا کہ اللہ تعالیٰ نے فرمایا ہے: ﴿وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا ٨١ كَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا﴾ (سورۂ مریم: ۸۱-۸۲) انہوں نے اللہ کے علاوہ معبود بنا رکھے ہیں تاکہ وہ ان کے لئے عزت بن سکیں۔ ہرگز نہیں، وہ تو ان کی عبادت کا انکار کریں گے اور انہی کے مخالف بن جائیں گے۔ (طبری:۱۹؍۳۶۳)\nبتوں کو انسان کا دشمن کیوں کہا گیا حالانکہ وہ جمادات ہیں؟\nٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ ٧٨ وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ ٧٩ وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ ٨٠ وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ ٨١ وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ ٨٢\nپس میرا رب وہی ہے جس کے ہاتھ میں میرا نفع اور نقصان ہے،جس کے لئے ساری بادشاہت اور طاقت ہے،دنیا اورآخرت کامالک وہی ہے۔میرا رب ایسا نہیں ہے کہ کوئی پکارے اور وہ نہ سنے اور نہ نفع ونقصان پہنچائے۔ ابراہیم علیہ السلام کی طرف سے یہ گفتگو دراصل اپنی قوم کے ساتھ اس بات پر حجت پیش کرنا تھا کہ عبادت اور بندگی صرف اسی ذات کے لئے زیبا ہے جو یہ سارے اعمال کرسکتا ہو نہ کہ اس ذات کے لئے جو کسی نفع ونقصان کی طاقت نہ رکھتا ہو۔ (طبری: ۱۹؍۳۶۳)\nوہ عقلی دلیلیں کیا ہیں جو ابراہیم علیہ السلام نے اللہ تعالیٰ کی ربوبیت کو ثابت کرنے کے لئے اور غیر اللہ کی ربوبیت کو باطل کرنے کے لئے ذکر کیں؟\nوَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ ٨٠\nاللہ تعالیٰ کے ساتھ ادب واحترام کی خاطر بیماری کو اپنی ذات کی طرف اور شفا کو ذات باری تعالیٰ کی طرف منسوب کیا۔ (ابن جزی: ۲؍۱۱۹)\nآیت کریمہ میں ایک ادب کا بیان ہے جس کا خیال اللہ کے ساتھ رکھنا مناسب ہے۔ وہ کیا ہے؟\nwords\nتَرَاءَىهر گروه نے دوسروں كو ديكھا.\nفِرقٍسمندر كا ايك حصه.\nكَالطَّودِجيسے پهاڑ.\nوَأَزلَفنَا ثَمَّهم نے وهاں قريب كرديا / فرعون اور اس كي قوم كو."],[371,"§الشعراء\ndeeds\nاپنے والدین کے لئے مغفرت ورحمت کی دعائیں مانگئے.\nاسی سے دوستی کیجئے جس کی دوستی آپ کو اللہ سے قریب کردے.\nصرف اللہ کی رضا کے لئے کسی مسلمان کو قرآن کی کوئی سورت سکھائیے.\nguid\nاپنے دل کی نگرانی کیجئے اور اس کی اصلاح کی کوشش کیجئے اس لئے کہ وہی کامیاب ہوگا جو پاکیزہ دل لے کر اللہ کے پاس حاضر ہوگا.\nاُن فاسقوں کے راستوں سے محتاط رہئے جو لوگوں کو گمراہ کرتے ہیں یقینا اللہ نے جہنم کوایسے ہی لوگوں کا ٹھکانہ بنایا ہے.\nاچھے دوست بنانے کی حرص رکھئے، اس لئےکہ امید ہے کہ اللہ کی اجازت سے وہ قیامت کے دن آپ کے لئے سفارش کریں.\nrefl\nوَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ ٨٤\n(لسان صدق في الآخِرين) اس سے مراد ابراہیم علیہ السلام کی تعریف وتوصیف اور ذکرِخیر ہے اور ان کے مقام و مرتبہ کا ہمیشہ باقی رہنا ہے جیسا کہ مفسرین کا اس پر اتفاق ہے۔ (ابن عطیہ: ۴؍۲۳۵)\nسچی زبان سے کیا مراد ہے؟\nيَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ ٨٨ إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ ٨٩\nایسی صورت میں مطلب یہی ہوگا کہ یہ مال اسی وقت فائدہ پہنچائیگا جب اسے اللہ کی فرمانبرداری میں خرچ کیا جائے۔(ابن جزی: ۲؍۱۱۹)\nقیامت کے دن بندے کا مال کب نفع بخش ہوگا؟\nإِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ ٨٩\nخاص طور سے دل کوذکر کیا گیا کیونکہ اس کے صحیح رہنے سے بدن کے سارے اعضاء صحیح رہتے ہیں اور اس کے بگڑنے سے بدن کے دیگر اعضاء بگڑجاتے ہیں۔ (القرطبی: ۱۶؍۴۴)\nاللہ تعالیٰ نے خاص طور سے دل کو کیوں ذکر کیا؟\nوَجُنُودُ إِبۡلِيسَ أَجۡمَعُونَ ٩٥\n(وجُنُودُ إِبلِيسَ)ابلیس کے لشکر سے مراد اس کی نسل اور اس کے پیروکار بھی ہیں کیونکہ وہ بھی اس کے لشکر کاحصہ اور اس کے مدد گار ہیں۔ (ابن عطیہ: ۴؍۲۳۶)\nانسان ابلیس کے لشکر میں سے کب ہوجاتا ہے؟\nفَمَا لَنَا مِن شَٰفِعِينَ ١٠٠ وَلَا صَدِيقٍ حَمِيمٖ ١٠١\nقتادہ رحمہ اللہ نے فرمایا:انہیں معلوم ہے کہ بیشک نیک دوست نفع بخش ہوتا ہے اور جگری نیک دوست سفارش کرنے والا ہوتا ہے۔ (ابن کثیر:۳؍۳۲۹)\nیہ آیت کریمہ نیک اور اچھے دوست بنانے پر کیسے ابھارتی ہے؟\nإِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ\n(إذ قال لهم أخوهم)یہاں نسبی بھائی مراد ہے۔اور بیشک اللہ تعالیٰ نے رسولوں کو انہی کی قوم کے نسب میں سے بھیجا تاکہ قوم کے لوگ ان کی پیروی کرنے سے ناک بھوں نہ چڑھائیں اور تاکہ انہیں ان کی حقیقت معلوم رہے،اور تلاشنے کی ضرورت نہ پڑے۔ (السعدی؍۵۹۴)\nاللہ تعالیٰ نے رسولوں کو ان کی قوم کے نسب میں سے ہی کیوں بھیجا؟\nقَالُوٓاْ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ ١١١\nاس سے ان کے حق سے تکبراور حقائق سے جہالت کا پتہ چلتا ہے کیونکہ اگر ان کا مقصد حق کو اپنانا ہوتا تو وہ دعوت کے سلسلہ میں کسی اشکال اور شک پر کہتے:جو کچھ آپ لے کر آئے ہیں اس کے صحیح ہونے پر بہتر طریقوں سے ہماری رہنمائی کریں۔(السعدی؍۵۹۴)\nحق سے ان کے تکبر کرنے پر یہ آیت کریمہ کیسے دلالت کرتی ہے؟\nwords\nلِسَانَاچھي تعريف.\nالآخِرينان كے بعد قيامت تك آنے والے.\nسَلِيمٍشرك و نفاق او ركينه سے محفوظ.\nوَأُزلِفَتِاور قريب كردي گئي.\nوَبُرِّزَتِظاهر كردي گئي.\nفَكُبكِبُواوه جمع كئے گئے/ او رڈالے گئے.\nحَمِيمٍوه مشفق جو همارے امور كا اهتمام كرے.\nكَرَّةًدنيا كي طرف واپسي.\nالأَرذَلُونَگرے هوئے نيچ لوگ."],[372,"§الشعراء\ndeeds\nکمزور اور مسکین نیک لوگوں کے پاس جاکر بیٹھئے اور انہیں تحفے دیجئے.\nاللہ سے دعا کیجئے کہ ظالموں کو ظالموں کے ذریعہ ہی ہلاک کرے او ر مسلمانوں کو ان کے بیچ سے صحیح سلامت نکال دے.\nکوئی نصیحت سنئے اور جو سنئے اس پر عمل کی کوشش کیجئے.\nguid\nظالم اور سرکش لوگ جب دلیلوں کے سامنے بے بس ہوجاتے ہیں تو قوت کا سہارا لینے لگتے ہیں.\nظلم بڑھ جائے تو اللہ سے فتح اور نجات مانگنا مشروع ہے.\nنوح علیہ السلام کا صبرطویل ہوا تو ان کی دعا بھی جلد قبول ہوئی.\nrefl\nقَالَ وَمَا عِلۡمِي بِمَا كَانُواْ يَعۡمَلُونَ ١١٢\nنوح علیہ السلام نے اپنی قوم سے کہا:مجھے کیا معلوم میرے پیروکار کیا کرتے ہیں،میں تو ان کا ظاہر جانتا ہوں نہ کہ باطن اور باطن کے علم کا مکلف بھی نہیں ہوں،میں تو صرف ظاہر کا مکلف ہوں،چنانچہ جس نے ظاہر میں اچھا کیا اسے میں اچھا سمجھوں گا اور جس نے ظاہر میں براکیااسے میں برا سمجھوں گا۔ گویا آپ کہہ رہے ہیں:بیشک ان کے باطنی معاملات کا حساب جن کا علم مجھے نہیں ہے وہ میرے رب کے ذمہ ہے،کاش!یہ بات تم سمجھ سکتے۔کیونکہ میرا رب تو ان کا باطن اور ظاہر سب جانتا ہے۔ (طبری۱۹؍۳۷۰)\nایک داعی لوگوں کے ظاہری حالات کا ذمہ دار ہے نہ کہ باطنی معاملات کا۔آیت کی روشنی میں اس کی وضاحت کریں.\nوَمَآ أَنَا۠ بِطَارِدِ ٱلۡمُؤۡمِنِينَ ١١٤ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ ١١٥\nلگتا ہے کہ قریش کی طرح انہو ں نے بھی کمزوروں کو بھگانے کا مطالبہ کیا تھا (إن أنا إلا نذير مبين) یعنی اللہ نے مجھے فقراء کو چھوڑکر صرف مالداروں کے پاس نہیں بھیجا ہے۔ بیشک میں ایک رسول ہوں اور تبلیغ میری ذمہ داری ہے جو میری بات مانے گا وہ عنداللہ کامیاب اور نیک بخت ہوگاچاہے وہ فقیر ہی کیوں نہ ہو۔ (القرطبی: ۱۶؍۵۳)\nکیا دعوت مالداروں کے ساتھ خاص ہے؟آیت کی روشنی میں اس کی وضاحت کیجئے.\nأَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ ١٢٨\nوعظ ونصیحت کا مقام منکَر کام کے مٹانے سے کہیں زیادہ بڑھ کر ہے۔چنانچہ ہود علیہ السلام کی نصیحت سیدھا ان کی روحانی بیماریوں کی طرف متوجہ ہے۔ انہوں نے جو نشانیاں اور صنعتیں بنائیں انہیں بدلنے سے متعلق ان کی نصیحت بالکل نہیں ہے۔ (ابن عاشور: ۹۱؍۶۶۱)\nکیا ہود علیہ السلام نے عمارتیں بنانے پر اپنی قوم کی نکیر کی؟\nأَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ ١٢٨ وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ ١٢٩ وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِينَ ١٣٠\nہود علیہ السلام کا اپنی قوم کو اس انداز میں ڈانٹنا اس بات پر دلالت کرتا ہے کہ ان کے دلوں میں کس قدر دنیا کی محبت اور تکبر وگھمنڈ بیٹھ چکے تھے۔یہاں تک کہ اسی دنیا پرستی اور غرور نے انہیں اللہ کی بندگی سے بے نیاز کردیاتھا۔ (الوسی: ۱۰؍۱۰۸)\nدنیا کی محبت میں حد سے تجاوز کرنے کا کیا اثر ہوتا ہے؟\nأَمَدَّكُم بِأَنۡعَٰمٖ وَبَنِينَ ١٣٣\nنعمتوں کے شمار کرانے میں ہود علیہ السلام نے سب سے پہلے چوپایوں کا ذکر کیاہے اس لئے کہ ان لوگوں کے لئے یہی سب سے بڑی نعمت تھی کیونکہ انہی سے وہ اپنا رزق اورلباس حاصل کرتے تھے اور انہی پر سفر کرتے تھے۔ (ابن عاشور: ۱۹؍۱۷۰)\nآیت کریمہ میں چوپایوں کو سب سے پہلے کیوں ذکر کیا گیا؟\nقَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ ١٣٦\nقوم عاد طاقت وقوت اور سلطنت میں اس قدر بڑھی ہوئی تھی کہ جس کی بنیاد پر انہوں نے یہ بات کہہ ڈالی: ﴿مَنۡ أَشَدُّ مِنَّا قُوَّةً﴾ (سورۂ فصلت: ۱۵)یعنی طاقت میں ہم سے بڑھ کر کون ہے؟ ایک لمبی مدت تک انہوں نے ایسی ہی زندگی گذاری جس میں انہوں نے اپنی خواہشات ِنفس کو پورا کرنے میں خوب فنکاری سے کام لیا،لذت وآسائش میں خوب مگن ہوئے اور اپنے آپ پر خوب گھمنڈ کیا یہاں تک کہ دین اور تزکیۂ نفس جیسے اہم انسانی پہلوؤں کو گنوا بیٹھے،اللہ سبحانہ وتعالیٰ کے حقوق میں کوتاہی کی او ر نصیحت کرنے والوں کو بے وقوف سمجھا۔ (ابن عاشور: ۱۹؍۱۶۵)\nاللہ کے ذکر سے غافل سماج پرنعمتوں کی کثرت کی خطرناکی واضح کیجئے.\nقَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ ١٣٦\n(قالوا سواء علينا أوعظت أم لم تكن من الواعظين) یعنی ہمارے لئے سب برابرہے۔ہم کسی طور تم سے کوئی بات سننے والے نہیں ہیں اور جو کچھ تم ہم سے کہہ رہے ہو اس کی طرف بھی ہم کچھ دھیان دینے والے نہیں ہیں۔ (القرطبی: ۱۶؍۵۹)\nسخت دل والوں کو جب نصیحت کی جاتی ہے اور اللہ یاد دلایاجاتا ہے تو ان کا کیا حال ہوتا ہے؟\nwords\nالمَرجُومِينَپتھر مار كر هلاك كئے هوئے.\nفَافتَحپس فيصله كردے.\nالمَشحُونِبھري هوئي.\nرِيعٍاونچي جگه.\nآيَةًاونچي تعمير.\nتَعبَثُونَتم اسے ديكھتے هو/ گزرنے والوں كا مذاق كرتے هو.\nمَصَانِعَمحفوظ محلات ؛ مضبوط قلعے.\nأَمَدَّكُماس نے تمهيں ديا/ تم پر انعام كيا.\nسَوَاءٌ عَلَينَاهمارے نزديك برابرهے."],[373,"§الشعراء\ndeeds\nبذریعہ پیغام دعاۃ کو نصیحت کیجئے کہ اخلاص اور دعوت کے عوض دنیا طلب نہ کرنا ان کی دعوتی کامیابی کے اسبا ب میں سے ہے.\nاللہ سے اجر کی امید رکھتے ہوئے کسی مسلمان کو صبح وشام کے کچھ اذکار سکھائیے.\nبذریعہ پیغام کفار ومنافقین کی خطرناکی اور زمین میں ان کے فساد کے کچھ نمونے لوگوں کے سامنے پیش کیجئے.\nguid\nجھٹلانے والوں کی تحقیر اور مذاق اڑانے کی پرواہ نہ کیجئے بیشک یہ جاہل کمزور وں کے حیلوں میں سے ہے.\nامانت داری ہر امت اور ہر دور کے رسولوں اور سچے داعیوں کا شعار رہی ہے.\nگناہ اور نافرمانی کے کاموں میں سرکشوں کی اطاعت بہت نقصان دہ ہے اس لئے کہ اس کا انجام بھیانک ہوتا ہے.\nrefl\nفَكَذَّبُوهُ فَأَهۡلَكۡنَٰهُمۡۚ\nاللہ رب العالمین نے قرآن کریم میں مختلف جگہوں پر ان کے ہلاک وبرباد ہونے کی وجہ بتائی ہے کہ ان پر تیز وتند سخت ٹھنڈک والی آندھی بھیجی گئی تھی کیونکہ وہ بہت سخت دلی کی صفت کے حامل تھے چنانچہ انہیں اسی طرح بلکہ اس سے بھی زیادہ سخت اور تیز وتند عذاب سے ہلاک کیا گیا۔(ابن کثیر:۳؍۳۳۱)\n“جیسی کرنی ویسی بھرنی”اس مقولہ کو قوم عاد کی سزا کی روشنی میں واضح کیجئے.\nكَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِينَ ١٤١\nانہوں نے صالح علیہ السلام کو جھٹلادیا جنہوں نے ان کو اس توحید کی طرف بلایا تھا جس کی طرف تمام رسولوں نے بلایا ہے چنانچہ ان کا آپ کو جھٹلانا گویا سارے رسولوں کو جھٹلانا ہوا۔ (السعدی؍ ۵۹۶)\nقوم ِثمود کا سارے رسولوں کو جھٹلانا کیسے لازم آتا ہے؟\nوَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ١٤٥\nتاکہ تم یہ نہ کہو کہ ہم تمہاری پیروی اس لئے نہیں کررہے ہیں کیونکہ تم ہم سے مال ودولت طلب کررہے ہو (إن أجري إلا على رب العالمين) ہم تو صرف اللہ رب العالمین ہی سے ہر طرح کا بدلہ اور ثواب طلب کرتے ہیں۔ (السعدی؍ ۵۹۶)\nآیت میں اللہ کے سچے ولیوں کی سچائی کی کیا علامت ہے؟\nأَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ ١٤٦\n(أتتركون) یہ انہیں خوف دلانے کے لئے کہا جارہا ہے کہ کیا تمہارے کفر کے باوجود تمہیں ان نعمتوں میں چھوڑدیا جائیگا۔(ابن جزی: ۲؍۱۲۱)\nکیا کسی سماج میں گناہوں کے باوجود نعمتیں ہمیشہ باقی رہ سکتی ہیں؟\nأَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ ١٤٦\n(في ما هاهنا) جملہ کے اندر پائی جانے والی پوشیدگی کو (آمنين) حال واقع ہو کر واضح کررہا ہے۔اور یہ ایک ایسی عظیم نعمت ہے جس پر اسم اشارہ دلالت نہیں کرتا کیونکہ یہ اشارہ کرنے والی چیز ہی نہیں ہے۔یہ امن وسلامتی کی نعمت ہے جو سب سے بڑی نعمتوں میں شمار ہوتی ہے بلکہ دوسری نعمتوں کا مزہ اس کے بغیر سمجھا ہی نہیں جاسکتا۔ (ابن عاشور: ۱۹؍۱۷۵)\nامن وسلامتی کی نعمت عظیم نعمتوں میں سے کیوں مانی جاتی ہے؟\nٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ ١٥٢\nصرف(يفسدون)کے ذکر کرنے سے کبھی کبھی ان کی اصلاح کی نفی نہیں ہوتی ہے تو (ولا يصلحون) یعنی اصلاح کی نفی کا جملہ لایا گیا تاکہ ان کے فسادی ہونے کی انتہا کو واضح کیا جاسکے اور یہ کہ اصلاح نام کی کوئی چیز ان کے یہا ں تھی ہی نہیں۔ (الوسی: ۱۰؍۱۱۳)\nافساد اور عدم اصلاح دونوں صفتوں کو ایک ساتھ اکٹھا کرنے کا کیا فائدہ ہے؟\nفَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ١٥٨\n(إن أجل الله إذا جاء لا يؤخَّر) جب قوم ثمود کو عذابِِالہٰی کا یقین ہوگیا تو وہ اونٹنی کے ہاتھوں اور پیروں کو زخمی کرنے اور پھر اسے قتل کرنے پر شرمندہ ہوئے، یہ اس وقت ہوا جب صالح علیہ السلام نے انہیں تین دن کی مہلت دی اور ہر دن عذاب کی علامتیں ظاہر ہونی شروع ہوگئیں جنہیں دیکھنے کے بعد وہ اپنے فعل پر نادم ہوئے لیکن ایسے وقت میں ندامتیں کام نہیں آتیں۔ اور ایک تفسیر یہ کی گئی ہے کہ ندامت اس لئے مفید نہیں ہوئی کیونکہ انہوں نے توبہ نہیں کی۔ (القرطبی: ۱۶؍۶۷)\nقوم ثمود کے عذاب کی صفت بیان کیجئے.\nwords\nخُلُقُدين او رعادت.\nطَلعُهَا هَضِيمٌاس كا پھل پكا هوا نرم هے.\nفَارِهِينَاس كو كھودنے كے ماهر / خوش هونے والے/اكڑنے والے.\nالمُسرِفِينَالله تعاليٰ كي نافرماني ميں بهت آگے جانے والے.\nشِربٌپاني كا حصه.\nفَعَقَرُوهَااس كو نحر كرديا."],[374,"§الشعراء\ndeeds\nیہ دعا مانگئے: “اَللّٰهُمَّ کَرِّهْ اِلَيَّ الْکُفْرَ وَالْفُسُوْقَ وَالْعِصْيَانَ”۔اے اللہ! تو میرے نزدیک کفر،فسق اور اپنی نافرمانی کو ناپسند بنادے.\nغلط کام سے منع کیجئے اور پھر ایک پیغام بھیج کر یہ واضح کیجئے کہ اگر امت امر بالمعروف اور نہی عن المنکر کی ادائیگی میں سستی برتے گی تو اس كے اندر برائیوں کی ترغیب دينا اور بھلائیو ں سے روكنا عام ہوجائے گا۔اللہ کی پناہ!\nکم تولنے کے نقصان اور اس کے انجام وسزا پر ایک پمفلٹ تیار کرکے اپنے محلہ کے دوکانداروں میں تقسیم کیجئے.\nguid\nدل سے اللہ کی محبت نکل جائے تو بے شمار غیر فطری امور انجام پانے لگتے ہیں.\nمظلوم کی بددعا ضرور قبول ہوتی ہے اور خاص طور سے جبکہ وہ نیک لوگوں میں سے ہو.\nجب برائیاں عام ہوجائیں اور ظلم وفساد بڑھ جائے تو اللہ کے عذاب کا انتظار کیجئے.\nrefl\nأَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ ١٦٥\nآیت کا مفہوم یہ ہے کہ دنیا کے اندر نرومادہ کی جتنی بھی قسمیں پائی جاتی ہیں ان میں سے کسی بھی قسم کا نرنر کے پاس نہیں جاتا ہے لیکن تم لوگ اس معاملہ میں سارے جہاں کی مخالفت کرتے ہو۔چنانچہ اس میں اس بات کی جانب تنبیہ ہے کہ یہ بھیانک عمل فطرت کے خلاف ہے جو گونگے حیوانوں کے یہاں بھی نہیں پایا جاتا۔لہٰذا یہ ان کا ایجاد کردہ ایسا انوکھا عمل ہے جسے ان سے پہلے کسی نے نہیں کیا۔ (ابن عاشور: ۱۹؍۱۷۹)\nآیت کریمہ نے قوم ِلوط کے عمل کی قباحت کو کیسے بیان کیا ہے؟\nقَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ ١٦٧\nیہ ان کی وہی بات ہے جیسی پہلے لوگوں نے کہی تھی، جس طرح کفر میں ان کے دل ایک دوسرے سے مشابہ ہیں اسی طرح ان کی باتیں بھی ایک دوسرے سے ملتی جلتی ہیں۔ (السعدی؍۵۹۶)\nپہلے اور آج کے مجرموں کے درمیان باتوں کی مشابہت کس چیز پر دلالت کرتی ہے؟\nقَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ ١٦٨\nلوط علیہ السلام نے کہا: (إني لعملكم من القالين)یعنی میں تمہارے عمل سے دوررہتا ہوں۔ “القلی” ناپسندیدگی اور چھوڑنے ودرکنار کرنے کو کہتے ہیں۔ اور انبیاء علیہم السلام تو اللہ کے ولی ہوتے ہیں،وہ وہی پسند کرتے ہیں جو اللہ کو پسند ہو اور وہ ناپسند کرتے ہیں جو اللہ کو ناپسند ہو۔ (ابن تیمیہ: ۵؍۴۵)\nآیت کی روشنی میں اللہ کے ولیوں کی کوئی ا ہم صفت واضح کیجئے.\nرَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ ١٦٩\n(ربِّ نجني وأهلي مما يعملون) مطلب یہ ہے کہ ان کرتوت کے بدلہ میں قوم کو جو عذاب ملنے والا ہے اس سے لوط علیہ السلام اور ان کے متبعین کو بچالے۔لوط علیہ السلام جب ان کے ایمان لانے سے مایوس ہوگئے تو اللہ سے یہ دعا کی ۔ (القرطبی: ۱۶؍۶۹)\nعذاب کے آنے سے اللہ کے نبی لوط علیہ السلام کس قدر خائف تھے،اس کی شدت کو واضح کیجئے.\nفَنَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ ١٧٠ إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ ١٧١\n(إلا عجوزًا) اس بوڑھی عورت سے مراد لوط علیہ السلام کی بیوی تھی جو پیچھے رہ جانے والوں کے حکم میں شامل تھی۔اور اسے اسی عذاب سے دوچار ہونا ہے جو قوم لوط پر آنے والا ہے کیونکہ ازل ہی سے ہم نے اسے نہ بچانے کا فیصلہ کرلیا تھا کیونکہ اس نے اپنے شوہر کے دین کی پیروی نہیں کی تھی بلکہ اس کی مرضی اس کی قوم کے ساتھ تھی۔ (البقاعی: ۱۴؍۸۳)\nدین کا تعلق نسب کے تعلق سے زیادہ مضبوط ہوتا ہے۔آیت کی روشنی میں اسے واضح کیجئے.\nإِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ١٧٨ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ١٧٩ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ١٨٠\nبیشک تمام انبیاء علیہم السلام کی دعوت اللہ تعالیٰ کے بیان کے مطابق ایک ہی منہج پر تھی کیونکہ تقویٰ،اطاعت اور عبادت میں اخلاص ، دعوتِ دین پر اجرت نہ لینے اور تبلیغ رسالت میں سب ایک دوسرے سے متفق تھے۔ (البغوی: ۳؍ ۳۷۱)\nوہ کون سی صفتیں ہیں جن میں تمام رسول اپنی دعوت میں متفق تھے؟\nأَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ ١٨١ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ ١٨٢\nمطلب پورا پورا وزن کرنے کا حکم ہے اور کمی کرنے سے روکا گیا ہے،زیادتی کرنے سے نہیں۔اور بہ ظاہر یہی لگتا ہے کہ شعیب علیہ السلام نے زیادتی کرنے سے منع نہیں کیا ہے اور انہیں ناپنے تولنے میں زیادتی کرنے کا حکم نہیں دیا گیا ہے گویا یہ اس بات کی دلیل ہے کہ اگر کوئی زیادہ تولتا ہے تو اچھا اور جو ایسا نہیں کرتا تو اس کی پکڑ نہیں ہے۔ (الوسی: ۱۰؍ ۱۱۷)\nناپنے تولنے میں زیادتی کرنے پر خاموشی کس بات پر دلالت کرتی ہے؟\nwords\nعَادُونَحلال و حرام ميں الله تعاليٰ كي مباح كرده سے تجاوز كرنے والے.\nالقَالِينَتمهارے اعمال سے بهت سخت بغض ركھنے والے.\nالغَابِرِينَعذاب ميں پڑے رهنے والے.\nأَصحَابُ الأَيكَةِباغوں والي زمين كے مالك / مراد قوم حضرت شعيب.\nالمُخسِرِينَلوگوں كے حقوق ميں كمي كرنے والے.\nبِالقِسطَاسِميزان كے ساتھ."],[375,"§الشعراء\ndeeds\nقرآن کریم میں کچھ جگہوں پر شعیب علیہ السلام کی قو م کا قصہ پڑھئے اور اس کے فوائد پر غور کیجئے.\nایک پیغام لکھ کر کسی مسلمان کو قرآن کریم کی کسی آیت سے نصیحت کیجئے.\nعربی زبان میں لکھا ہوا کوئی مضمون اس نیت سے پڑھئے کہ اس طرح آپ قرآن کریم کو سمجھ سکیں گے.\nguid\nآپ کو قرآن کی جو آیات یاد ہوں اور جن کے معانی سمجھتے ہوں اس کے ذریعہ اپنے ساتھ بیٹھنے والوں کو اللہ سے ڈرائیے.\nدل مرجائے تو آدمی اللہ کے عذاب کو ناممکن سمجھنے لگتاہے.\nعیش پرستی کتنی ہی زیادہ ہو اور مدت کتنی ہی دراز ہوجائے، یہ چیزیں بندے کو حساب اور بدلہ سے نہیں بچاسکتیں.\nrefl\nفَأَسۡقِطۡ عَلَيۡنَا كِسَفٗا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ١٨٧ قَالَ رَبِّيٓ أَعۡلَمُ بِمَا تَعۡمَلُونَ ١٨٨ فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ\nچونکہ ان لوگوں نے آسمان سے اپنے اوپر عذاب کا ٹکڑا لانے کا سوال کیا تھا اس لئے اللہ تعالیٰ نے اسی جنس سے انہیں سزادی۔یعنی سات دن مسلسل انہیں سخت گرمی لاحق رہی جس سے انہیں کوئی چیز بچا نہ پائی۔پھر ایک بدلی نے آکر ان پر سایہ کردیا سب لوگ اس بادل کے نیچے اکٹھے ہوگئے تو اللہ تعالیٰ نے یکایک ان کے اوپر اس بادل سے آگ کی چنگاریاں،شعلے اور بھڑکتی ہوئی آگ چھوڑدی اور نیچے سے زمین نے انہیں خوب ہلایااور پھر ایک سخت چیخ آئی جس سے سب کی جان نکل گئی۔ (ابن کثیر: ۳؍ ۳۳۵)\nشعیب علیہ السلام کی قوم کو اسی جنس سے عذاب دیا گیا جس کا انہو ں نے مطالبہ کیا تھا۔اس کی وضاحت کیجئے.\nإِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ١٩٠\nاگر کہا جائے کہ اس جملہ (إن في ذلك لآية وما كان أكثرهم مؤمنين) کو ہر قصہ کے ساتھ باربار کیوں ذکر کیا گیا ہے؟تو اس کا جواب یہی ہوگاکہ یہ نصیحت پکڑنے میں زیادہ بلیغ ہے اور دلوں کو تنبیہ کرنے میں زیادہ سخت ہے۔اور چونکہ ہر قصہ ایک مستقل کلام کی حیثیت رکھتا ہے اسی لئے ہر قصہ کے اختتام پر وہی جملہ دہرایا گیاجو پہلے قصہ کے خاتمہ پر مذکور تھا۔(ابن جزی: ۲؍ ۱۲۳)\nسورت میں ہر قصہ کے بعد (إن في ذلك لآية وما كان أكثرهم مؤمنين) ذکر کرنے سے کیا فائدہ ہے؟\nوَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ ١٩٢\nوہ ہستی جس نے اس عظیم کتاب کو نازل فرمایا ہے وہ زمین وآسمان کو پیدا کرنے والا اور تمام عالم ِعلوی اور سفلی کا مربی ہے۔جس طرح اس نے بندو ں کی جسمانی اور دنیاوی مصلحتوں میں رہنمائی فرماکر ان کی تربیت کی،اسی طرح وه ان کے دین وآخرت کی مصلحتوں میں بھی رہنمائی فرماکر ان کی تربیت کرتا ہے۔اورسب سے عظیم چیز جس کے ذریعہ اللہ تعالیٰ نے اپنے بندوں کی تربیت کی ہے وہ اس کتابِ کریم قرآن مجید کا نازل فرمانا ہے جو بے انتہا بھلائی اور بے پایاں نیکی پر مشتمل ہے۔ اور اس کے اندر دنیا و آخرت کی مصلحتوں اور اخلاق فاضلہ کی ایسی رہنمائیاں ہیں جو دوسری کتابوں میں نہیں ملتی ہیں۔ (السعدی: ۵۹۷-۵۹۸)\nاللہ تعالیٰ نے اس جگہ اپنے آپ کو (رب العالمين) کہا ہے،اس کا کیا فائدہ ہے؟\nوَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ ١٩٢ نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ ١٩٣ عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ ١٩٤ بِلِسَانٍ عَرَبِيّٖ مُّبِينٖ ١٩٥\nآپ غور کیجئے کہ کیسے یہ تمام عمدہ و فاخر فضائل اس عظیم کتاب میں جمع ہوگئے ہیں کہ یہ کتاب سب سے افضل کتاب ہے،اسے سب سے افضل فرشتہ لے کر نازل ہوا،اس ہستی پر نازل ہوئی جو مخلوق میں سب سے افضل ہے اوران کے جسم کا سب سے افضل حصہ یعنی آپ صلی اللہ علیہ وسلم کے دل پر نازل ہوئی،سب سے افضل امت پر نازل ہوئی جو تمام لوگوں کے لئے برپا کی گئی اور سب سے افضل،سب سے فصیح اور سب سے وسیع و واضح عربی زبان میں نازل ہوئی۔ (السعدی: ۵۹۸)\nان سارے فضائل کے بارے میں گفتگو کریں جو قرآن مجید سے متعلق ہیں.\nأَوَ لَمۡ يَكُن لَّهُمۡ ءَايَةً أَن يَعۡلَمَهُۥ عُلَمَٰٓؤُاْ بَنِيٓ إِسۡرَٰٓءِيلَ ١٩٧\nبیشک اگر کسی معاملہ میں شبہ واقع ہوجائے تو باصلاحیت وتجربہ کار اہل علم کی طرف رجوع کیا جاتا ہے اور ان کا قول دوسروں پر حجت ہوتا ہے جیسے ان جادوگروں نے جو جادوکے علم میں ماہر تھے موسیٰ علیہ السلام کے معجزے کی صداقت اور اس کی سچائی پہچان لی اور یہ کہ وہ کوئی جادو نہیں ہے۔لہٰذا اس کے بعد جاہل اور لاعلم لوگوں کے قول کو اہمیت نہیں دی جائے گی۔ (السعدی؍ ۵۹۸)\nبنی اسرائیل کے علماء کا علم یہاں کیوں خاص کیا گیا کہ ان کا علم اس قرآن پاک کی سچائی کے لئے کافی ہے؟\nفَيَقُولُواْ هَلۡ نَحۡنُ مُنظَرُونَ ٢٠٣\nیعنی تاکہ ہم ایمان لائیں اور تصدیق کریں، وہ لوٹنے اور مہلت کی تمنا کریں گے۔ (البغوی: ۳؍ ۳۷۳)\nعذاب آجانے کے بعد رسولوں کو جھٹلانے والے کس بات کی تمنا کریں گے؟\nأَفَرَءَيۡتَ إِن مَّتَّعۡنَٰهُمۡ سِنِينَ ٢٠٥\nمطلب یہ ہے کہ مہلت کی مدت بے سود ہوگی اگر اس کے بعد عذاب آجائے گرچہ اس مہلت کی مدت سالہاسال پر مشتمل ہوکیونکہ ہر آنے والا وقت قریب ہی ہوتا ہے۔ (ابن جزی: ۲؍ ۱۲۴)\nانسان اگر گناہوں پراڑا ہواہو تو لمبی عمر اسے کیافائدہ دے سکتی ہے؟\nwords\nوَالجِبِلَّةَسابقه امتيں/ مخلوق.\nالمُسَحَّرِينَبهت سخت جادو كئے گئے؛ حتي كه ان كي عقل ماري جائے.\nكِسَفًاعذاب كا ايك حصه.\nالظُّلَّةِبادل كو سايه فگن ٹكڑا ؛ جس كے نيچے ٹھنڈك محسوس كرنے لگے.\nزُبُرِ الأَوَّلِينَسابقه انبياء كي كتابيں.\nالأَعجَمِينَجو عربي زبان نهيں بول سكتے."],[376,"§الشعراء\ndeeds\nاپنے کچھ رشتہ داروں کے ساتھ مل کر دعوتی پروگرام مرتب کیجئے اور اس میں اچھی باتوں اور قریب کرنے والے ہدیوں کے ذریعہ اپنے رشتہ دارو ں کو فائدہ پہنچائیے.\nتہجد پڑھئے اور خوب لمبے سجدے کیجئے.\nعمومی اور خصوصی اذکار کے ذریعہ اللہ تعالیٰ کا ذکر کیجئے مثلاً سو مرتبہ“سُبْحَانَ اللّٰهِ وَبِحَمْدِهٖ”کہئے اور سوبار استغفار کیجئے.\nguid\nجو اللہ کے علاوہ کی عبادت پر مرے وہ عذاب پانے والوں میں ہوگا.\nبردباری،تواضع اور نرمی کے بغیر داعی اپنی دعوت میں کامیاب نہیں ہوسکتا.\nظلم سے بچئے اور ظالموں کے برے انجام کو یاد رکھئے نیز اپنے آس پاس کے ظالموں اور سرکشوں کے احوال پر غور کیجئے کہ اللہ نے کس طرح انہیں تباہ کردیا.\nrefl\nمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يُمَتَّعُونَ ٢٠٧\nاللہ تعالیٰ فرمارہا ہے: میری نشانیوں کے انکار اور رسولوں کو جھٹلانے کی وجہ سے جس عذاب کا میں نے ان سے وعدہ کیا تھا وہ ان پر آچکا ہے۔ (ما أغنى عنهم) یعنی ان کی عمروں کو طویل کرکے ہم نے ان کے ساتھ جو تاخیر کی،انہیں ڈھیل دی اور انہیں ہر سامان ِزیست سے نوازا لیکن پھر بھی انہوں نے توبہ نہیں کی بلکہ وہ فساد مچانے اور بگڑنے میں مزید بڑھتے چلے گئے۔تو کیا ان ساری چیزوں نے انہیں کچھ فائدہ پہنچایا؟۔ بلکہ مزید گناہوں سے ان کا ہی مزید نقصان ہوا اور اگر انہیں اتنی ڈھیل نہیں دی جاتی تو یہ اتنے سارے جرم کرکے یہ گناہ حاصل نہیں کرتے۔ (طبری: ۱۹؍۴۰۲)\nعمل صالح کے بغیر لمبی عمر ہلاکت کا سبب ہے۔ واضح کیجئے.\nفَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِينَ ٢١٣\nباوجودیکہ رسول اللہ صلی اللہ علیہ وسلم منع کردہ چیزوں کا ارتکاب نہیں کرسکتے تھے پھر بھی آپ کومزید اخلاص پر جوش دلانے اورابھارنے کے لئے اس طرح مخاطب کیا گیا ۔ چنانچہ اس میں اس بات کی جانب کنایہ ہے کہ توحید میں اتنے مخلص ہوجاؤ کہ اللہ کے سوا کوئی اور نہ دکھائی دے۔ ساتھ ہی اس میں تمام مکلف بندوں کے لئے لطیف ہدایت یہ ہے کہ شرک ایسی بری اور قبیح چیز ہے کہ اس سے ایسے شخص کو بھی روکا جاتا ہے جس سے اس کا صادر ہونا ممکن نہیں ہے تو بھلا دوسروں کا کیا حال ہوسکتا ہے۔ (الوسی: ۱۰؍ ۱۳۱)\nنبی صلی اللہ علیہ وسلم کو شرک کرنے سے منع کیا جارہا ہے حالانکہ آپ سے شرک کا ارتکاب محال ہے۔ اس کا کیا فائدہ ہے؟\nوَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ ٢١٤\nیہ حکم تمام لوگوں کو ڈرانے کے حکم کے منافی نہیں ہے۔جیسے انسان کو پہلے عمومی احسان کا حکم دیا جاتا ہے پھر اس سے کہا جاتا ہے “اپنے قریبی رشتہ داروں کے ساتھ اچھا سلوک کرو ”۔ اس وقت یہ خاص حکم تاکید اور حق کے زیادہ ہونے پر دلالت کرتا ہے۔ (السعدی: ۵۹۹)\nکیا اس آیت سے یہ سمجھا جائے کہ نبی صلی اللہ علیہ وسلم کی دعوت آپ کی قوم کے ساتھ خاص تھی؟\nوَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ ٢١٥ فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ ٢١٦\n(فإن عصوك)یہ آیت کریمہ ان لوگوں کے وہم کی تردید کرتی ہے جو کہتے ہیں کہ اللہ تعالیٰ کا ارشاد: (واخفض جناحك لمن اتبعك من المؤمنين) اہل ایمان سے صادر ہونے والے ہر فعل پر رضا اور خوشی کا تقاضہ کرتا ہے۔اس وہم کو اس بیان کے ذریعہ دور کیا جارہا ہے۔ (السعدی: ۵۹۹)\n(واخفض جناحك لمن اتبعك من المؤمنين)کے بعد(فإن عصوك) کا جملہ کیوں لا یا گیا ہے؟\nوَتَقَلُّبَكَ فِي ٱلسَّٰجِدِينَ ٢١٩\nآیت کا مطلب یہ ہے کہ اللہ تبارک وتعالیٰ دوسرے تمام نمازیوں کے ساتھ آپ کی نماز کو بھی دیکھتا ہے چنانچہ اس میں نماز کوجماعت کے ساتھ پڑھنے کی طرف بھی اشارہ ہے۔ (ابن جزی: ۲؍ ۱۲۴)\nیہ آیت کریمہ نماز باجماعت پڑھنے پر کیسے دلالت کررہی ہے؟\nيُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَٰذِبُونَ ٢٢٣\n(يلقون)مطلب یہ ہے کہ سنی ہوئی باتوں کو دوسروں تک پہنچاتے ہیں۔اس سے مراد شیاطین ہوسکتے ہیں جو سنی ہوئی باتوں کو کاہنوں تک پہنچاتے ہیں۔ یا اس سے مراد کاہن بھی ہوسکتے ہیں جو شیطان سے باتوں کو سن کر دوسرے لوگوں تک پہنچاتے ہیں(وأكثرهم كاذبون) اس سے شیطان مراد ہیں اور کاہن بھی ہوسکتے ہیں جو شیطان سے سنی ہوئی باتوں کے بارے میں جھوٹ سے کام لیتے ہیں۔ (ابن جزی: ۲؍ ۱۲۵)\nنجومیوں او ر کاہنوں کو جھوٹی باتیں کہاں سے ملتی ہیں؟\nأَلَمۡ تَرَ أَنَّهُمۡ فِي كُلِّ وَادٖ يَهِيمُونَ ٢٢٥\nمطلب یہ ہے کہ وہ لغو اور بیکار باتوں میں مست رہتے ہیں اور حق کے راستوں پر نہیں چلتے ہیں کیونکہ جو حق کی پیروی کرتا ہے اور یہ جانتا ہے کہ اس کی ہر بات لکھی جاتی ہے وہ تحقیق سے کام لیتا ہے اور مست مولا ہوکر بلا سوچے سمجھے کچھ بھی نہیں بولتا۔ (القرطبی: ۱۶؍۹۵)\nاس شخص کے بارے میں آپ کاکیا خیال ہے جو گپ مارنے والوں کے ساتھ گپ مارے، جو من میں آئے بولتا رہے اور حق کی پیروی نہ کرے؟\nwords\nالسَّمعِآسمانوں سے قرآن كا سننا.\nلَمَعزُولُونَضرور روكے گئے هيں۔ شهابيے مارے جاتے هيں.\nوَاخفِض جَنَاحَكَاپنے پهلو كو نرم ركھ ۔ گفتار ميں نرمي پيدا كر.\nأَفَّاكٍبهت جھوٹا.\nأَثِيمٍبهت گنهگار.\nوَادٍباطل فنون ميں سے ايك فن / جھوٹ.\nيَهِيمُونَوه سرگرداں پھرتے هيں.\nمُنقَلَبٍپلٹنے كي جگه."],[377,"§النمل\ndeeds\nپورے خشوع اور نماز کے واجبات وسنتوں کے ساتھ مساجد میں باجماعت نمازوں کا اہتمام کیجئے.\nکسی محتاج کو صدقہ دیجئے.\nاللہ تعالیٰ سے اس کے دوناموں علیم (علم والے)اور حکیم (حکمت والے) کے واسطہ سے دعائیں مانگئے کہ وہ آپ کو علم اور حکمت سے نوازے اور قرآن یاد کرنے کی توفیق دے.\nguid\nقرآن کریم کے اعجاز کا بیان کہ اس کی آیات “طس”اور “حم” جیسے حروف سے مرکب ہیں مگر پوری مخلوق اس جیسا کلام پیش کرنے سے عاجز ہے.\nنمازکو اس کے ارکان وشروط اورخشوع کے ساتھ پابندی سے ادا کیجئے۔تاکہ آپ قرآن کی آیات سے فائدہ اٹھاسکیں.\nدوبارہ زندہ کئے جانے اور آخرت کا انکار آدمی کو مخلوق میں بدترین بنادیتا ہے اور اس کی حالت جانوروں سے بھی گئی گزری ہوجاتی ہے.\nrefl\nهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ ٢ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ\nبسا اوقات اگر کہا جائے کہ ایمان کے دعویدار تو بہت زیادہ ہوتے ہیں تب کیا ہر اس شخص کی بات قبول کرلی جائے جو ایمان کا دعویٰ کرتا ہے یا اس پر کوئی دلیل ضروری ہے؟ اور یہی بات(ایمان پر دلیل کا ہونا) صحیح بھی ہے، اسی لئے اللہ تعالیٰ نے اہل ایمان کی صفات بیان کرتے ہوئے فرمایا ہے: (الذين يقيمون الصلاة) یعنی یہ وہ لوگ ہیں جو نماز قائم کرتے ہیں۔ (السعدی؍ ۶۰۱)\nایمان کے دعویداروں کی سچائی کی کیا پہچان ہے؟\nوَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ ٣\nآخرت پر ان کا یقین تقاضہ کرتا ہے کہ وہ اس میں سرخرو ہونےکی پوری کوشش کریں،عذاب کے اسباب اور اس کے موجبات یعنی عذاب الٰہی میں مبتلا کرنے والے اعمال سے بچیں اور یہی ہر بھلائی وخیر کی بنیاد ہے۔ (السعدی؍ ۶۰۱)\nیوم آخرت پر ایمان کس بات کا تقاضہ کرتا ہے؟\nإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ٤\nان اعمال سے مراد ان کے ظاہری اور باطنی تمام شرکیہ اعمال ہیں۔چنانچہ ان کے اِن اعمال سے مانوس ہونے اور ان میں سخت ہونے کی وجہ سے وہ اس کتاب سے ہدایت حاصل کرنے کے اہل نہ ہوسکےجس کی ساری آیتیں اور نشانیاں ان کے سامنے آئیں۔ (ابن عاشور:۱۹؍۲۲۰)\nآیت کریمہ کی روشنی میں غلطی پر اصرار کا انجام واضح کیجئے.\nإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ٤\n(إن الذين لا يؤمنون بالآخرة ) یعنی جو لوگ آخرت پر ایمان نہیں لاتے اور اپنے ایمان کی تجدید نہیں کرتے ہیں (زينا لهم أعمالهم فهم يعمهون) ہم نے اپنی ناقابل تسخیر عظمت و قدرت سے ان کے قبیح اعمال کو مزین کردیاہےیہاں تک کہ وہ لوگ اس کی قباحت کے وضوح و ظہور کے باوجود اس کے انجام سے بے خوف ہوگئے ۔ (البقاعی: ۱۴؍۱۲۷)\nاگر آخرت پر آپ کا ایمان کمزور ہے تو اس سے کیا لازم آئیگا؟\nإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ٤\nشیطان ان کے قبیح اعمال کو وسوسوں کے ذریعہ اس طرح مزین کردیتا ہے کہ ان کے دل اسے قبول کرلیتے ہیں،جیسا کہ اللہ تعالیٰ نے شیطان ہی کی زبانی ذکر کیا ہے: ﴿قَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ٨٢ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ﴾ (سورۂ ص: ۸۲-۸۳)تیری عزت وجلال کی قسم!میں ان سب کو گمراہ کرکے چھوڑوں گا سوائے ان میں تیرے مخلص بندوں کے۔ صیغۂ مضارع (يَعْمَهُوْنَ)سے پتہ چلتا ہے کہ گمراہی اور اندھ بھکتی ان کے اندر ہمیشہ رہتی ہے اور اس کی تجدید ہوتی رہتی ہے اس لئے وہ ہدایت کی طرف کبھی نہیں آپاتے ہیں کیونکہ وہ اپنے آپ کو حق پر سمجھتے ہیں اور معلوم ہونا چاہئے کہ گمراہی اور اندھ بھکتی میں استمرار مختلف درجوں کا ہوتا ہے ان میں سب سے سخت وہ ہوتا ہے جو اپنے ساتھی کو اسی حالت میں موت تک پہنچادیتا ہے اور کچھ اس سے کمتر ہوتے ہیں۔اور ہر درجہ ان کے دلوں میں کفر کے مزین ہونے کے اعتبار سے چھوٹا بڑا ہوتا ہے۔ (ابن عاشور: ۱۹؍۲۲۱)\nآیت کریمہ نے اس راستہ کی وضاحت کی ہے جس کے ذریعہ شیطان انسان کو گمراہ کرتا ہےوہ راستہ کون سا ہے؟\nوَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ ١٠\n(لَدَيَّ)“ميرے پاس”کی قید لائی گئی ہے کیونکہ لوگوں میں سب سے زیادہ اللہ سے ڈرنے والے ہمیشہ رسول ہی رہے ہیں۔اللہ تعالیٰ نے فرمایا ہے: ﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْ﴾(سورۂ فاطر: ۲۸) بیشک اللہ کے بندوں میں اس سے سب سے زیادہ علماء ڈرتے ہیں۔اور رسولوں سے زیادہ اللہ کے بارے میں کوئی نہیں جانتا۔(الوسی: ۱۰؍۱۵۹)\nرسولوں کو (لَدَيَّ) یعنی“ میرے پاس” کے ساتھ قید کرنے کا کیا راز ہوسکتا ہے؟\nيَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ ١٠ إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوٓءٖ فَإِنِّي غَفُورٞ رَّحِيمٞ ١١\nاگر کوئی کہے: توبہ اور مغفرت کے بعد خوف کا کیا مطلب ہے؟ تو اس کا جواب یہ ہوگا کہ: اللہ عزوجل کے بارے میں علماء کا یہی طریقہ رہا ہے کہ وہ گناہوں سے ہمیشہ خائف رہتے ہیں نیز اس بات سے بالکل مامون نہیں رہتے کہ ہوسکتا ہے توبہ کی شرطوں میں سے کوئی شرط باقی رہ گئی ہو جسے پورا نہ کیا جاسکا ہو،اس لئے وہ اس سے متعلق بازپرسی سے خوفزدہ رہتے ہیں۔ (القرطبی: ۱۶؍۳۳۰)\nتوبہ واستغفار کے بعد بھی اللہ کے نیک بندے اپنے گناہوں سے کیوں ڈرتے ہیں؟\nwords\nيَعمَهُونَوه اپنے برے اعمال ميں حيران هيں.\nلَتُلَقَّىآپ ديے جاتے هيں.\nمِن لَدُنكي طرف سے.\nآنَستُميں نے ديكھا هے.\nبِشِهَابٍآگ كا شعله.\nتَصطَلُونَتم گرمي حاصل كرو.\nمُبصِرَةًظاهر ؛ واضح."],[378,"§النمل\ndeeds\nتین ایسی نعمتیں یا دکیجئے جو اللہ نے خصوصیت سے آپ کو دی ہیں،پھر انبیاء کرام علیہم السلام کی پیروی کرتے ہوئے ان پر اللہ تعالیٰ کا شکر ادا کیجئے.\nچیونٹیوں کی زندگی پر غور کیجئے یا ان کی زندگی کے بارے میں کوئی علمی پروگرام سنئے اور پھر اس سے حاصل ہونے والے تین فوائد لکھئے.\nیہ دعا مانگئے \"رب أزعني أن أشكر نعمتك التي أنعمت عليَّ وعلى والديَّ، وأن أعمل صالحًا ترضاه، وأدخلني برحمتك في عبادك الصالحين\".\nguid\nان مواقع پر مسکرائیے جہاں مسکرانا چاہئے،اور ترش روئی سے بچئے.\nاللہ تعالیٰ آپ کے والدین میں سے کسی کوکوئی نعمت دے تو اس پر اللہ کا شکر ادا کیجئے اس لئے کہ ماں باپ کی نعمت اولاد کے لئے بھی نعمت ہوتی ہے۔ اور اللہ کا شکر اوراس کی تعریف نعمتوں کے باقی رہنے کے اسباب میں سے ہے.\nاللہ جسے کسی معاملہ کا ذمہ دار بنائے تو تقویٰ کا تقاضہ ہے کہ وہ اپنے ماتحتوں اور ذمہ داریوں کا خیال رکھے.\nrefl\nفَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ١٤\nخطاب کا مفہوم یہ ہے کہ اسے محمد صلی اللہ علیہ وسلم کو جھٹلانے والو!اور آپ کی رب کی جانب سے لائی ہوئی شریعت کا انکار کرنے والو!آگاہ ہوجاؤکہیں وہی عذاب تم پر بھی نہ آجائے کیونکہ تم اس کے زیادہ مستحق ہو اس لئے کہ محمد صلی اللہ علیہ وسلم موسیٰ علیہ السلام کے مقابلے میں زیادہ اشرف اور عظیم ہیں اور آپ کی دلیلیں موسیٰ علیہ السلام کی دلیلوں سے زیادہ قوی اور مضبوط ہیں۔(ابن کثیر: ۳؍۳۴۵-۳۴۶)\nآیت کے اندر محمد صلی اللہ علیہ وسلم کی نبوت کا انکار کرنے والوں کو ڈرایا گیا ہے حالانکہ گفتگو موسیٰ علیہ السلام کی نبوت کے منکرین سے متعلق ہے۔ اس کی وضاحت کیجئے.\nوَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرٖ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ ١٥\nیہ بندے کی سعادت کی علامت ہے کہ وہ تمام دینی اور دنیاوی نعمتوں پر اللہ تعالیٰ کا شکر ادا کرے اور یہ ایمان رکھے کہ تمام نعمتیں صرف اس کے رب کی طرف سے عطاہوتی ہیں۔ وہ ان نعمتوں پر فخر کرے نہ ان پر تکبر کرے بلکہ یہ سمجھے کہ ان نعمتوں کا لازمی تقاضہ یہ ہے کہ ان پر اللہ تعالیٰ کا بے انتہا شکر ادا کیا جائے۔ (السعدی؍۶۰۲)\nآیت کی روشنی میں واضح کیجئے کہ نیک بندوں پر نعمتوں کا اثرکیسے ہوتا ہے؟\nوَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ\nیعنی سلیمان علیہ السلام بادشاہت اور نبوت دونو ں میں داؤد علیہ السلام کے وارث بنے۔اس سے مال کی وراثت مرادنہیں ہے کیونکہ اگر ایسا ہوتا تو داود علیہ السلام کی اولاد میں سے صرف سلیمان علیہ السلام کو خاص نہ کیا جاتا اس لئے کہ انبیاء علیہم السلام کےمال ودولت وارثین میں تقسیم نہیں کئے جاتے ہیں۔ (السعدی؍۳۴۶)\nسب سے اچھی چیز جو اولاد اپنے والد سے وراثت میں حاصل کرتی ہے وہ ایمان،علم اور حکمت ہے۔آیت کی روشنی میں اس کی وضاحت کیجئے.\nفَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا\nزجّاج نے کہا:انبیاء علیہم السلام کی ہنسی اکثر مسکراہٹ ہوتی تھی اور یہاں ہنسنے سے مراد مسکرانا ہے۔ (البغوی: ۳؍۳۹۱)\nانبیاء علیہم السلام کا ہنسنا اکثر کیسا ہوتا تھا؟\nوَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَا لِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ ٢٠ لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ ٢١\nآیت کریمہ اس بات پر دلالت کرتی ہے کہ حاکم کو رعایا کے احوال دیکھتے رہنا چاہئے اور اس کی دیکھ بھال کرتے رہنا چاہئے۔دیکھیں ایک معمولی پرندہ ہدہد کی حالت سے بھی سلیمان علیہ السلام بے خبر نہیں ہیں پھر آپ اپنی بادشاہت کی بڑی بڑی چیزوں کے بارے میں کتنے فکر مند رہتے ہوں گے؟اللہ عمر رضی اللہ عنہ پر رحم فرمائے!آپ بھی رعایا کی دیکھ بھال میں انہی کی طرح تھے،آپ کہاکرتے تھے: اگر دریائے فرات کے کنارے کسی بکری کے بچے کو بھیڑیا اٹھالے جائے تو عمر کو اس کا بھی جواب دینا ہوگا۔ (القرطبی: ۱۶؍۱۳۱)\nکیا حکومت اور امارت بس لائق شرف و فخر ہے یا ایسی امانت اور ذمہ داری ہے جس کے بارے میں قیامت کے دن سوال ہوگا؟آیت کی روشنی میں اس کی وضاحت کیجئے.\nلَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ ٢١\nیعنی وہ اپنے پیچھے رہ جانے کے جواز پر واضح دلیل پیش کرے۔یہ سلیمان علیہ السلام کے کمال ِعدل وانصاف اور تقویٰ کی دلیل ہے کہ آپ نے ہدہد کو یوں ہی سخت عذاب دینے یا قتل کرنے کی قسم نہیں کھائی کیونکہ یہ سزا صرف بہت بڑے جرم کی پاداش میں ہی دی جاسکتی ہے۔ اور ہدہد کی غیر حاضری میں کسی واضح عذر کا احتمال بھی ہوسکتا تھا اس لئے آپ نے اپنے ورع وتقویٰ اور ذہانت کی بناپر اس کو مستثنیٰ کردیا۔(السعدی؍۶۰۴)\nسلیمان علیہ السلام کے ورع وتقویٰ،سنجیدگی اور جلد بازی نہ کرنے پر یہ آیت کیسے دلالت کرتی ہے؟\nفَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۢ بِنَبَإٖ يَقِينٍ ٢٢\nہدہدکےاس دفاع اور جواب میں اس بات کی تنبیہ ہے کہ ایک کمزور سی مخلوق کو وہ علم و صلاحیت عطا ہوتی ہے جو طاقتور سے طاقتور مخلوق کو نہیں دی جاتی تاکہ علماء اپنے علم کو کمتر سمجھیں اور ہر شیئ کے علم کو اللہ کی طرف لوٹادیں۔اس آیت کے اندر روافض کے اس قول کا توڑبھی ہے کہ امام پر کوئی چیز پوشیدہ نہیں ہوتی ہے اور اس کے زمانے میں اس سے بڑا کوئی عالم نہیں ہوتا۔ (البقاعی:۱۴؍۱۵۰)\nسلیمان علیہ السلام کی مملکت اور علم کی کشادگی اور زیادتی کے باوجود ہدہد کی معرفت اور جانکاری کس بات پر دلالت کرتی ہے؟\nwords\nيُوزَعُونَا ن كے اول كو آخر پر لوٹايا جاتا هے؛ تاكه سارے انتظام كے ساتھ كھڑے هوں.\nأَوزِعنِيمجھے الهام كردے.\nسَبَإٍيمن كا ايك شهر."],[379,"§النمل\ndeeds\nآج آپ نے کوئی خبر سنی ہوتو اچھی طرح اس کی تحقیق کرلیجئے کیونکہ خبروں کی تحقیق کرلینا قرآنی منہج ہے جس سے صالحین غافل نہیں رہتے.\nاپنے محلہ میں آپ جو غلط کام دیکھیں اس پرٹوکیں۔دیکھئے کہ ہدہُد پرندہ نے بھی شرک پر ٹوکا.\nہدیہ دل میں محبت ڈالتا ہے لہذا آپ جس کی ہدایت کی امید رکھتے ہوں اسے ہدیہ دیجئے.\nguid\nعقلمند عورت کی کمزوری جانتا ہے لہذا اس پر ایسے اعمال کا بوجھ نہیں ڈالتا جو اس کے لئے مناسب نہیں.\nیاد رکھئے کہ شیطان اللہ کے ذکر سے غافل رہنے والوں کے لئے ہی برے اعمال مزین کرتا ہے اور بندے کو اللہ کی اطاعت سے روکتا ہے.\nمستحب ہے کہ کتابچوں،کتابوں اورخطبوں کی شروعات بسم اللہ سے کی جائے.\nrefl\nإِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ ٢٣ وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ ٢٤\nابوبکرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کو جب یہ خبر پہنچی کہ اہل ِفارس نے کسریٰ کی بیٹی کو بادشاہت سونپ دی ہے تو آپ نے فرمایا:وہ قوم کبھی کامیاب نہیں ہوسکتی جو اپنے معاملات کسی عورت کو سونپ دے۔ (بخاری) (الالبغوی: ۳؍۴۹۹)\nآیت کریمہ سے کوئی ایک فائدہ نکالئے.\nأَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ ٢٥\nیہ لوگ اس ذات کی عبادت کیوں نہیں کرتے جسے ہر کمال حاصل ہے،اس سجدہ کے ذریعہ جو اُنس ومحبت کی جگہ، قربت کا ٹھکانہ،آہ وزاری کا در اور عافیت کی نشانی ہے۔یقینا ًوہ اگراللہ تعالیٰ کو سجدہ کرتے تو ہدایت پر ہوتے کیونکہ نماز تمام منکرات اور برائیوں سے انسان کو دور رکھتی ہے اور اس وقت شیطان انسان کو گمراہ کرنے کے اپنے مقصد میں کامیاب نہیں ہوپاتا۔(البقاعی: ۱۴؍ ۱۵۲-۱۵۳)\nانسانی زندگی میں اللہ کے لئے سجدہ کا کیا اثر ہوتا ہے؟\n۞قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ ٢٧\nاللہ تعالیٰ کا فرمان:(أصدقت أم كنت من الكاذبين) اس بات پر دلیل ہے کہ حاکم کو چاہئے کہ رعایا کا عذر قبول کرے اور ان کے ذاتی عذر کو سن کر ظاہر پر محمول کرتے ہوئے سزاؤں کو معاف کردے کیونکہ سلیمان علیہ السلام نے ہُدہد کوسزا نہیں دی جب اس نے اپنا عذربیان کردیا اور ہدہد کی سچائی کو ہی عذر مانا گیا۔ (البغوی: ۳؍۴۵۹)\nانبیاء علیہم السلام کی یہ سنت ہے کہ باتوں کی تحقیق کی جائے۔اسےآیت کی روشنی میں واضح کیجئے.\nقَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ ٣٢\nآیت سے اس بات پر دلیل لی گئی ہے کہ مشورہ کرنا اور اہم معاملات میں دوسروں کے آراء و خیالات اور مشوروں سے مدد لینا مستحب اور بہتر ہے۔ (الالوسی: ۱۰؍۱۹۲)\nاہم معاملات آپ کس طرح حل کرنے کی کوشش کرتے ہیں؟\nإِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ٣٠\nاس آیت سے پتہ چلتا ہے کہ کتابوں کی ابتداء مکمل “بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ” لکھ کر کرنا مستحب ہے۔ (السعدی: ۶۰۴)\nلکھتے ہوئے ابتداء میں کیا مستحب ہے؟\nوَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ ٣٥\nامام قتادہ رحمہ اللہ نے فرمایا: اللہ ملکہ سبا پر رحم فرمائے اور اس سے راضی ہو!وہ اسلام اور شرک دونوں حالتوں میں کس قدر عقلمند تھی۔اسے علم تھا کہ ہدیہ لوگوں کے دلوں پر کس طرح اثر کرتا ہے۔ ابن عباس رضی اللہ عنہ وغیرہ نے فرمایا:اس نے اپنی قوم سے کہا:اگر وہ ہدیہ قبول کرتے ہیں تو سمجھو بادشاہ ہیں، ایسی صورت میں ان سے جنگ کرو اور اگر قبول نہیں کرتے تو سمجھو وہ نبی ہیں،ایسی صورت میں ان کی پیروی کرو۔ (ابن کثیر: ۶؍۱۹۰)\nحکمت ودانائی کے ساتھ برتاؤ کرنا ہدایت کا ذریعہ ثابت ہوسکتا ہے۔ آیت کی روشنی میں اسے واضح کیجئے.\nوَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ ٣٥\nاس نے اپنی قوم سے کہا: میں ایک عمدہ ہدیہ سے اس شخص کو پرکھتی ہوں۔اگر یہ دنیاوی بادشاہ ہوگا تو یہ مال اسے خوش کردیگا اور اگر نبی ہوگا تو یہ مال اسے خوش نہیں کرسکے گا بلکہ ہمارا دین میں داخل ہونا ہی اسے خوش کریگا۔ اس غرض سے اس نے بہترین ہدیہ بھیجا۔(ابن جزی: ۲؍ ۱۳۰)\nملکہ سبا نے سلیمان علیہ السلام کی سچائی کا پتہ لگانے کے لئے کیا ذریعہ اختیار کیا؟ اور اس کے اس طرح کے تعامل سے آپ کیا فائدہ حاصل کرتے ہیں؟\nwords\nالخَبءَمستور/ آنكھوں سے اوجھل.\nالمَلأُلوگوں كے بڑے / سردار.\nتَعلُوا عَلَيَّميرے سامنے تكبر كرو.\nأَفتُونِيمجھے مشوره دو.\nقَاطِعَةً أَمرًاكسي كام كا فيصله كرنے والي.\nتَشهَدُونِتم ميرے پاس موجود هو.\nأُولُووالے/ اصحاب.\nفَنَاظِرَةٌپس انتظار كرتي هوں."],[380,"§النمل\ndeeds\nایک پیغام لکھ کر واضح کیجئے کہ دنیا کو دین پر فوقیت دینا کس قدر خطرناک ہے.\nرشوت سے خبردارکرنے کے لئے وعظ کیجئے یا بذریعہ موبائل پیغام بھیجئے.\nاللہ نے آپ کو جو نعمتیں دی ہیں ان میں سے تین کا خیال کیجئے اور ان پر اللہ کا شکر ادا کیجئے تاکہ آپ کو ان میں برکت حاصل ہو.\nguid\nآخرت کے طلبگاروں کے مقاصد اور دنیا والوں کے مقاصد مختلف ہوتے ہیں اسی لئے آخرت کو چاہنے والے دنیا سے اس طرح خوش نہیں ہوتے جس طرح دنیا والے ہوتے ہیں.\nجان لیجئے کہ سب سے بڑی نعمت دین کی نعمت ہے اور دنیا تو زائل ہونے والی ہے اس لئے مومن اس کی طرف مائل نہیں ہوتا.\nغور کیجئے کہ غِنیٰ اور کرم یہ دونوں صفات کس طرح اللہ کے حق میں جمع ہیں.\nrefl\nفَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٖ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرٞ مِّمَّآ ءَاتَىٰكُمۚ\nدراصل ملکہ سبا نے سلیمان علیہ السلام کے ہدیہ قبول کرنے یا رد کرنے کو اپنے دل میں سوچی ہوئی اس بات پر علامت بنایا تھا کہ وہ بادشاہ ہیں یا نبی۔کیونکہ سلیمان علیہ السلام نے اس کو خط میں یہ لکھا تھا: (ألا تعلوا عليَّ وأتوني مسلمين) میرے خلاف سرکشی نہ کرو اور میرے پاس فرمانبردار بن کر آجاؤ۔ اور یہ ایسی صورت ہے جس میں نہ تو فدیہ قبول ہوسکتا ہے اور نہ ہی ہدیہ لیا جاسکتا ہے۔ یہ شریعت کا وہ باب نہیں ہے جہاں ہدیہ لینا درست ہوتا ہے۔یہاں تو یہ رشوت ہوگا اور حق کو باطل کے ذریعہ بیچنا ہوگا اور یہ رشوت کسی صورت میں حلال نہیں ہوگی۔رہا وہ ہدیہ جو عام طور سے محبت ودوستی کی خاطر دیا جاتاہے تو وہ ہر ایک کے لئے ہر حال میں جائز ہے۔ (القرطبی: ۱۶؍۱۵۹)\nسلیمان علیہ السلام نے ہدیہ کورد کیوں کردیا؟\nبَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ ٣٦\nمطلب یہ ہے کہ تم لوگ ہدیہ دئے جانےپر خوش ہوتے ہو کیونکہ تمہاری نظریں صرف دنیا پر مرکوز ہیں اور تمہیں اس میں مزید کی چاہت ہے۔بلاشبہ اس جواب میں ملکہ اور اس کے ساتھیوں کی رسوائی ہے جو کسی سے مخفی نہیں ہے۔(الالوسی: ۱۰؍۱۹۵)\nحق وہدایت کے داعی کے لئے یہ بالکل مناسب نہیں ہے کہ وہ دنیا کی رنگینیوں سے دھوکے میں پڑے۔آیت سے آپ اسے کیسے سمجھیں گے؟\nقَالَ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا\nابوجعفر رحمہ اللہ نے کہا: سلیمان علیہ السلام نےاپنے لشکر کے سرداروں کو ملکہ سبا کی بادشاہت کی دوسری چیزوں کو چھوڑکر تخت شاہی ہی کو حاضر کرنے کا حکم کیوں دیا؟ ہمارے نزدیک راجح قول کے مطابق اس کی وجہ یہ ہے کہ تاکہ آپ اسے اپنی نبوت کے لئے دلیل بنائیں اور اس کے ذریعہ اللہ کی عظیم قدرت اور بلند شان سے اسے روشناس کرائیں کیونکہ ملکہ نے اس تخت کو ایسے بند کمرے میں رکھا تھا جو پے درپے کئی بند کمروں کے اندر تھا جنہیں کھولے بغیر اللہ تعالیٰ نے اپنے نبی علیہ السلام تک اسے پہنچادیا۔اس کے اندر ملکہ سبا کے لئےسب سے بڑی دلیل ہے اس حق پر جس کی جانب سلیمان علیہ السلام نے اسے بلایا تھا اور سلیمان علیہ السلام کی نبوت پر بھی اس واقعہ کے اندر دلیل ہےجس کی خبر آپ نے اسے دی تھی۔ (الطبری:۱۹؍۴۶۳)\nسلیمان علیہ السلام نے ملکہ سبا کی بادشاہت کی دوسری چیزوں کو چھوڑکر صرف تختِ شاہی کو ہی کیوں منگوایا؟\nقَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينٞ ٣٩ قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ\nدیوہیکل جن اور صاحب علم جن کے درمیان مناظرے سے پتہ چلتا ہے کہ علم وحکمت سے جو چیزیں حاصل کی جاسکتی ہیں وہ طاقت وقوت سے ممکن نہیں ہیں۔ (ابن عاشور: ۱۹؍۲۷۱)\nآیت کریمہ علم وحکمت کی فضیلت پر کیسے دلالت کررہی ہے؟\nفَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ\n(من فضل ربي) یعنی اللہ جل وشانہ کی طرف سے مجھ پر احسان وفضل ہے،میں نہ اس کا استحقاق رکھتا ہوں اور نہ ہی میرے پاس کوئی ایسا عمل ہے جو اللہ پر اسے واجب کرے۔ (الالوسی: ۱۰؍۱۹۹)\nنعمت پر سب سے بڑی شکر گزاری یہ ہے کہ اس کی نسبت اللہ عزوجل کی طرف کی جائے۔آیت سے اس کی وضاحت کیجئے.\nفَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ\n(قَالَ هَذَا مِن فَضلِ رَبِّي لِيَبلُوَنِي أَأَشكُرُ أَم أَكفُرُ) سلیمان علیہ السلام نے اپنے اقتدار،سلطنت اور طاقت سے کبھی فریب نہیں کھایاجیساکہ جاہل حکمرانوں اوربادشاہوں کی عادت ہے بلکہ آپ کو یقین تھا کہ یہ سب اللہ کی طرف سے ایک امتحان ہے۔لہٰذا وہ ڈرتے تھے کہ کہیں ایسا نہ ہو کہ وہ اس نعمت کا شکر ادا نہ کرسکیں۔پھر واضح کردیا کہ اس شکر سے اللہ تعالیٰ کو کوئی فائدہ نہیں پہنچنے والابلکہ اس کا فائدہ شکر کرنے والے ہی کی طرف لوٹتا ہے۔چنانچہ انہوں نے فرمایا: (وَمَن شَكَرَ فَإِنَّمَا يَشكُرُ لِنَفسِهِ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ)(السعدی: ۶۰۵)\nنیک صالح بادشاہوں اور جاہل بادشاہوں میں بنیادی فرق کیا ہے؟\nوَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ ٤٠\n(ومن شكر فإنما يشكر لنفسه) یعنی شکریہ ادا کرنے والے کو ہی اس کا فائدہ پہنچتاہے۔وہ اس طور پر کہ شکرسے نعمت کی تکمیل ہوتی ہے اور اسے دوام واستمرار حاصل ہوتا ہے کیونکہ شکرموجودہ نعمتوں کو قید کرلیتا ہےاور غیر موجود نعمتوں کو لے آتا ہے۔ (ومن كفر فإن ربي غني) یعنی میرا رب اس کے شکر سے بے نیازہےاور اس پر بھی کرم کرتا ہے جو اس کی نعمتوں پر ناشکری کرتا ہے۔ (البغوی: ۳؍۴۰۴)\nنعمتوں پر شکرادا کرنے کا کیا فائدہ ہے؟\nwords\nصَاغِرُونَذليل و رسوا هونے والے.\nعِفرِيتٌبهت سخت قوت والا سركش.\nنَكِّرُوااس كو بدل دو.\nالصَّرحَمحل / جس كے صحن ميں شيشے كے نيچے پاني تھا.\nمُمَرَّدٌجڑا هوا ؛ برابر كيا هوا.\nمِن قَوَارِيرَصاف شيشے سے."],[381,"§النمل\ndeeds\nبذریعہ پیغام یہ واضح کیجئے کہ بدفالی کا حکم صرف پرندوں سے ہی متعلق نہیں ہے بلکہ ہر اس چیز سے متعلق ہے جس سے بدشگونی لی جائے.\nبدشگونی کی کراہت کے سلسلہ میں آئی ہوئی یہ دعا یا د کیجئے “اَللّٰهُمَّ لَا طَيْرَ اِلَّا طَيْرُكَ، وَلَا خَيْرَ اِلَّا خَيْرُكَ، وَلَا اِلٰهَ غَيْرُكَ”۔اے اللہ! تیری حفاظت کے ہوتے بدشگونی نقصان نہیں پہنچاسکتی،خیر تیری ہی توفیق سے میسرہوتا ہے اور تیرے سوا کوئی معبود برحق نہیں ہے.\nاللہ سے دعا کیجئے کہ مسلمانوں کے خلاف کافروں کی تمام تدبیریں انہی کے خلاف الٹ جائیں.\nguid\nمومن ہمیشہ نیک فال لیتاہے اور نیک فال خیر کا ذریعہ بنتی ہے اور یہ اللہ کے ساتھ مکمل حسن ظن کا تقاضہ بھی ہے.\nیاد رکھئے کہ جو لوگوں کے ساتھ مکاری کرتا ہے اللہ اس کے مکر کو اسی کے خلاف الٹ دیتا ہے او راس کاوبال اسی پر آتا ہے.\nاس بات پر ہمارا یقین مضبوط ہے کہ اللہ تعالیٰ اپنے نیک بندوں کی مدد اور حفاظت کرتا ہے.\nrefl\nقَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ٤٧\n(قال طائركم عند الله) یعنی بحکم ِالٰہی جو خیر وشر تمہیں لاحق ہوتا ہے وہ پہلے سے مقدر ہوچکا ہے اور تقدیر کو طائر یعنی پرندہ کہا گیا ہے کیونکہ یہ بہت جلدی انسان پر اترتاہے اس لئے کہ فیصلہ کن تقدیر سے زیادہ تیز کوئی چیز نہیں ہوتی ہے۔ (البغوی: ۳؍۴۰۷)\nتقدیر کو پرندہ کیوں کہا گیا ہے؟\nقَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ٤٧\nرائے ومشورے اور تدبیر کے معاملہ میں بدشگونی کے اعتقاد سے بڑھ کر کوئی چیز نقصاندہ نہیں ہوتی ہے چنانچہ جس کا یہ اعتقاد اور خیال ہے کہ کسی گائے یا کوے کی آواز سے تقدیر بدل جاتی ہے یا کوئی مقدر ٹل جاتا ہےتو وہ سراسر جاہل ہے۔(القرطبی: ۱۶؍۱۸۱)\nانسان پر بدشگونی کی خطرناکی بیان کیجئے.\nقَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ٤٧\n(قالوا اطَّيَّرنا بك وبمن معك)اللہ انہیں برباد کرے۔ ان کا خیال تھا کہ انہیں صالح علیہ السلام کے چہرے میں کوئی خیر نظر نہیں آیا اور یہ کہ صالح علیہ السلام اور ان کے ساتھ دوسرے مومن ان کی بعض دنیوی خواہشات کے پورا ہونے میں رکاوٹ بن گئے ہیں چنانچہ صالح علیہ السلام نے ان سے کہا: (طائركم عند الله) یعنی تمہارے اوپر جو بھی مصیبت آتی ہے وہ تمہارے گناہوں کی وجہ سے آتی ہے۔ (بل أنتم قوم تفتنون) یعنی تمہیں خوشی وغمی اور خیر وشر کے ذریعہ آزمایا جائیگا تاکہ یہ معلوم ہوسکے کہ تم لوگ برائیوں سے باز آکر توبہ کرتے ہویا نہیں!(السعدی: ۶۰۶)\nانسان پر جو مصیبت اور پریشانی آتی ہے اس کا کیا سبب ہے؟\nوَمَكَرُواْ مَكۡرٗا وَمَكَرۡنَا مَكۡرٗا وَهُمۡ لَا يَشۡعُرُونَ ٥٠\nاللہ تعالیٰ نے ان کی سازش کو مکر کہا ہے کیونکہ چپکے سے کسی کو نقصان پہنچانے کی خاطر تدبیر کی گئی تھی۔ (ابن عاشور: ۱۹؍۲۸۴)\nآیت کریمہ میں سازش کو مکر کیوں کہا گیا ہے؟\nفَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ ٥٢\nکہا گیا ہے کہ یہ آیت اس بات پر دلالت کرتی ہے کہ ظلم گھر کی تباہی اور بربادی کا سبب بنتاہے۔ عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ انہوں نے کہا:میں اللہ کی کتاب میں پاتا ہوں کہ ظلم گھروں کو برباد کردیتا ہے۔اور انہوں نے یہ آیت پڑھی۔ تورات میں آیا ہے کہ: ابن آدم!ظلم نہ کر،ورنہ تیرا گھر برباد ہوجائیگا۔ کہا گیا ہے کہ اس آیت میں ظالم کی ہلاکت وبربادی کی طرف اشارہ ہے کیونکہ گھر کی بربادی اس کی ہلاکت کے پیچھے لگ جاتی ہے۔ اب یہ چیز ڈھکی چھپی نہیں رہ گئی کہ ظلم یعنی اللہ کے بندوں پر ظلم وستم گھرو ں کی تباہی کا سبب بنتا ہے جس کا مشاہد ہ اس زمانہ میں اکثر ہوتا رہتا ہے۔ (الألوسی: ۱۰؍۲۰۹)\nظلم کا سب سے بھیانک انجام کیا ہے؟\nفَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ ٥٢\nجب اللہ تعالیٰ نے قوم ثمود کے کفر و تکذیب اور فتنہ و فساد جیسے اعمال کو بطور خاص ظلم کی صفت سے ذکر کیا ہےتو اس میں اس بات کی طرف اشارہ ہے کہ بستیوں کی تباہی میں ظلم کا بڑا دخل ہوتا ہے۔ (ابن عاشور: ۱۹؍۲۸۵)\nاس آیت میں قوم ثمود کے عذاب کے اسباب میں صرف ظلم ہی کو کیوں ذکر کیا گیا ہے؟\nوَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ ٥٤\nیعنی یہ بد فعلی ایسا بھیانک اور قبیح عمل ہے جسے عقل او ر فطرت کے ساتھ تمام شریعتیں بھی برا گردانتی ہیں۔ (السعدی: ۶۰۷)\nقوم ِلوط کے جرم کو فحش عمل کیوں کہا گیا ہے؟\nwords\nاطَّيَّرنَاهم نے بدشگوني لي.\nطَائِرُكُم عِندَ اللهِتمهيں جو بھي بھلائي يا برائي پهنچے وه الله كي طرف سے مقدر هے.\nتَقَاسَمُواهر ايك نے دوسرے كے ليے قسم اٹھائي.\nلَنُبَيِّتَنَّهُهم رات كو اس كے پاس آكر قتل كريں گے۔ شبخون ماريں گے.\nخَاوِيَةًخالي."],[382,"§النمل\ndeeds\nاللہ سے دعا کیجئے کہ آپ کے لئے ایمان کو محبوب بناکراسے آپ کے دل میں مزین کردے،اور کفر،فسق نیز نافرمانی کو آپ کے لئے ناپسندیدہ بنادے.\nآج بھی اور ہمیشہ یہ دعا کثرت سے پڑھئے \"ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمامًا\".\nآپ اپنی کسی ایسی ضرورت کو یاد کیجئے جس کا حصول مشکل ہوگیا ہوتوخوب گڑگڑاکراور اصرار کے ساتھ اللہ سے دعا مانگئے کہ اسے آپ کے لئے میسر کردے.\nguid\nجب ظالم وسرکش لوگ دلیلوں کے آگے بے بس ہوجاتے ہیں تو طاقت کا سہارا لینے لگتے ہیں.\nآدمی کسی برائی کا عادی ہوجائے تو وہ اس کی نظر میں بری نہیں رہ جاتی.\nاپنے نیک بندوں کو نجات دینا اوردشمنوں کو ہلاک کردینا اللہ کا قانون ہے.\nrefl\n۞فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ لُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ٥٦\nمصیبت کا دارومدار زبان پر ہوتا ہے اسی لئے انہوں نے کہا: (أخرجوا آل لوط من قريتكم إنهم أناس يتطهرون) آل لوط کو اپنی بستی سے نکال باہر کرو،وہ بڑے پاکباز بنتے ہیں۔ اور اس کلام کا مفہوم یہ ہے کہ تم ایسی خباثت اور گندگی میں لتھڑے ہوئے ہو جس کا لازمی نتیجہ یہ ہے کہ تمہاری بستی پر عذاب آجائے، اور جو اس بستی سے نکل جائے وہ نجات پاجائے۔ (السعدی؍ ۶۰۷)\nقوم ِلوط کی زبان ان کی ہلاکت کا سبب بنی۔اس کی وضاحت کیجئے.\nفَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَٰهَا مِنَ ٱلۡغَٰبِرِينَ ٥٧\nیعنی وہ اپنی قوم کے ساتھ ہلاک ہونے والوں میں سے ہے کیونکہ وہ ان کے دین وعقیدے میں اور ان کے گھناؤنے اعمال کے انجام دینے میں ان کے طریقوں سے خوش تھی چنانچہ وہ لوط علیہ السلام کے پاس آئے ہوئے مہمانوں تک پہنچنے کے لئے قوم کی رہنمائی کرتی تھی۔ایسا بالکل نہیں ہے کہ وہ خود فحش کاموں میں مبتلا تھی اور وہ ایسا اپنے شوہر لوط علیہ السلام کی عزت کی خاطر کرتی تھی نہ کہ اپنی ذات کی خاطر۔ (ابن کثیر: ۳؍ ۳۵۶)\nلوط علیہ السلام کی بیوی کیوں ہلاک کردی گئی؟اور وہ اپنی قوم کے ساتھ کیسے تھی؟\nقُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ ٥٩\nحکم ہوا کہ آپ سلامتی بھیجیں ان تمام رسولوں پر جو پہلے گزر چکے ہیں اور اسی مقدار میں ان کی قدر کریں جتنا انہوں نے دین حق کی تبلیغ میں محنت کی ہے اور تکلیف اٹھائی ہے۔ (ابن عاشور: ۲۰؍۶)\nاللہ تعالیٰ کی تعریف کے بعد رسولوں پر سلامتی بھیجنے کا حکم کیوں آیا؟\nأَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارٗا وَجَعَلَ خِلَٰلَهَآ أَنۡهَٰرٗا وَجَعَلَ لَهَا رَوَٰسِيَ وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٦١\nیہ عجیب تدبیر ہے اور مکمل طور سے اس عجیب کاریگری کو وہی سمجھ سکتا ہے جسے اس بات کا علم ہو کہ زمین فضا میں تیر رہی ہے اور ہر لمحہ حرکت میں ہے جبکہ یہ زمین اس پر بسنے والوں کے لئے ٹھہری ہوئی ہے۔یہ بہت تعجب خیز تدبیر ہے جس میں ساتھ ساتھ رحمت اور نعمت بھی ہے۔اگر یہ زمین ٹھہری نہ رہتی تو لوگ ہمیشہ مضطرب،بے چین اور متزلزل رہتے اور ان کے لئے اس پر کام کرنا دشوار ہوتا۔ (ابن عاشور: ۲۰؍۱۳)\nزمین کے ساتھ اللہ تعالیٰ کی عظیم تدبیر اور کاریگری ہے۔ ہم اسے کیسے سمجھ سکتے ہیں؟\nوَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٦١\n(وجعل بين البحرين)دونوں سمندروں سے مراد ایک میٹھا اور دوسرا کھارا ہے۔ (حاجزًا) یعنی دونوں کے درمیان ایک رکاوٹ اور اوٹ ہے جو دونوں کو ایک دوسرے سے ملنے سے روکتی ہے۔کیونکہ اگر ایسا نہ ہوتو دونوں سے ضروری فائدے حاصل نہیں ہوپائیں گے۔ (السعدی: ۶۰۸)\nدونوں سمندروں کے درمیان رکاوٹ کیوں ڈال دی گئی؟\nأَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ ٦٢\nپریشان حال اور مجبور کی دعا سننے کی وجہ یہ ہے کہ پریشانی اور مجبوری کی وجہ سے انسان مخلص ہوجاتا ہے اور اللہ کے سوا اس کی ساری امیدیں ختم ہوجاتی ہیں اور اللہ تعالیٰ نے یہ خبر دی ہے کہ وہ مخلصین کی دعا قبول کرتا ہے چاہے وہ کافر ہی کیوں نہ ہو ں چنانچہ ارشاد باری ہے: ﴿حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ﴾(سورۂ یونس:۲۲)یہاں تک کہ جب تم کشتیوں میں ہوتے ہو اور وہ موافق ہواؤں کے سہارے تمہیں لے کر چل رہی ہوتی ہیں اور وہ ان کی رفتار سے خوش ہوتے ہیں کہ اچانک تیز ہوا ان کشتیوں کو آلیتی ہے اور موجیں ہر چہار جانب سے انہیں اپنے گھیرے میں لے لیتی ہیں اور انہیں یقین ہوجاتا ہے کہ وہ مکمل طور سے پھنس گئے ہیں تو وہ اللہ کو اس کے لئے بندگی بھرپور خالص کرتے ہوئے پکارتے ہیں کہ اے اللہ! اگر تو نے ہمیں اس مصیبت سے نجات دے دی تو ہم تیرے شکر گزار بندوں میں سے ہوجائیں گے۔ نیز فرمایا:﴿فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ﴾(سورۂ عنکبوت: ۶۵)اور جب اللہ تعالیٰ نجات دے کر انہیں خشکی تک پہنچادیتا ہے تو پھرشرک کرنے لگتے ہیں۔ یہاں دیکھئے کہ اللہ تعالیٰ نے ان کی ضرورت اور اخلاص کی وجہ سے ان کی دعا قبول کرلی حالانکہ اسے علم تھا کہ یہ دوبارہ شرک کریں گے۔ (الشوکانی:۴؍۱۶۹)\nپریشان حال شخص کے کافر ہونے کے باوجود اللہ تعالیٰ اس کی دعا کیوں قبول کرتا ہے؟\nأَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ ٦٢\nپریشان حال مجبور کی دعا قبول کرنے کی گارنٹی اللہ تعالیٰ نے دی ہے، نیز اپنی اس صفت کے بارے میں خبر دےدی ہے۔ اس کی دعا قبول ہونے کی وجہ یہ ہے کہ پریشان کن حالت میں ضرورت کی وجہ سے اخلاص پیدا ہوتا ہے اور اللہ کے سوا دوسروں سے دل کٹ جاتا ہے۔ اور یہ معلوم ہے کہ اللہ تعالیٰ کے یہاں اخلاص کی بڑی قیمت اور اس کی ضمانت ہے۔یہ اخلاص چاہے مومن کی طرف سے ہو یا کافر کی طرف سے۔ نیک فرمانبردار بندے کی طرف سے ہو یا نافرمان بندے کی طرف سے ہو۔ (القرطبی: ۱۶؍۱۹۳)\nوضاحت کیجئے کہ اللہ تعالیٰ سے دعا کرنے میں اخلاص کا کیا فائدہ ہے؟\nwords\nقَدَّرنَاهَاهم نے مقدر كرديا/ زوجه لوط كو ان ميں سے ركھا.\nالغَابِرِينَعذاب ميں پڑے رهنے والے.\nذَاتَ بَهجَةٍبهت خوبصورت منظر والا.\nيَعدِلُونَوه الله كے برابر اور اس كي نظير قرار ديتے هيں.\nخِلاَلَهَااس كے وسط ميں.\nرَوَاسِيَجمے هوئے پهاڑ."],[383,"§النمل\ndeeds\nجو لوگ ستاروں کی چالوں یا شعبدہ بازوں کے پاس جاکر غیب کی باتیں جاننے کی کوشش کرتے ہیں انہیں نصیحت کیجئے.\nپڑھئے او ر ظالمو ں کے انجام پر غور کیجئے.\nاپنے اوپر اللہ کی پانچ بڑی نعمتوں کویاد کیجئے اور ان پر اللہ کا شکر ادا کیجئے.\nguid\nعلم غیب اللہ تعالیٰ کا خاصہ ہے۔اگر کوئی غیب جاننے کا دعویٰ کرے تو وہ جھوٹا ہے.\nآخرت کے دن کو نہ ماننا آدمی کو گناہ پر جری بنادیتا ہے.\nقرآن کے طریقے کی اتباع کرنے میں ہی اختلاف اور تفرقہ سے حفاظت ہے.\nrefl\nقُل لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ ٦٥\nگزشتہ آیتوں نے جب واضح دلیلوں کے ذریعہ مشرکین کے بتوں کے معبود ہونے کو باطل قرار دیا اور اس سےعقیدۂ شرک کی جڑکٹ گئی تو اس کے فوراً بعد شرک کے ایک اثر کو باطل کرنا چاہا اور وہ ہے کہانت اور جنوں کی خبروں کی بنیاد پر علم غیب کا دعویٰ کرنا۔ (ابن عاشور: ۲۰؍۱۹)\nآیت کریمہ نے شرک کے ایک اثر کو باطل کیا ہے۔وہ کیا ہے؟\nبَلِ ٱدَّٰرَكَ عِلۡمُهُمۡ فِي ٱلۡأٓخِرَةِۚ بَلۡ هُمۡ فِي شَكّٖ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ ٦٦\nاللہ تعالیٰ نے آخرت کی تکذیب کرنے والوں کے احوال کے بارے میں ایک مرحلہ کے بعد دوسرے مرحلہ کی خبر دی کہ وہ کوئی علم نہیں رکھتے کہ قیامت کب آئیگی۔پھر اس کے بارے میں ان کی بے بضاعتی کی خبر دی۔پھر آگاہ فرمایا کہ وہ شک میں مبتلا ہیں۔پھر فرمایا کہ وہ اندھے ہیں۔پھر خبردی کہ وہ اس کا انکار کرتے اور اسے ناممکن سمجھتے ہیں۔ یعنی ان احوا ل کے سبب ان کے دلوں سے آخرت کا خو ف نکل گیا نتیجہانہوں نے اللہ کی نافرمانی پر اقدام کیا اوران کے لئے حق کو جھٹلانا اور باطل کی تصدیق کرنا معمولی بات ہوگئی، او ر عبادت کے مقابلہ میں انہوں نے شہوات کو حلال ٹھہرالیا پس اس طرح وہ دنیا وآخرت کے خسارے میں پڑگئے۔ (السعدی: ۶۰۹)\nوہ کیا وجہ تھی جس کی بنیاد پر کافروں نے مختلف گناہوں کے ارتکاب پر جرأت دکھائی؟\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ ٦٩\nپھر اللہ تعالیٰ نے جھٹلانے والوں کا انجام بیان کرکے انہیں نصیحت کی اور اپنے نبی صلی اللہ علیہ وسلم کو حکم دیا کہ اپنی قوم سے کہیں کہ ان مجرم قوموں کی حالت جاننے کے لئے ان کے ٹھکانوں کا معائنہ کریں،اور ہوشیار رہیں کہ کہیں انہیں بھی وہی عذاب نہ لاحق ہوجائے جو ان مجرم قوموں کو لاحق ہوا تھا۔ (ابن عطیہ: ۴؍ ۲۶۹)\nمجرم قوموں کی تاریخ پڑھنے کا کیا فائدہ ہے؟\nوَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُن فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ ٧٠\nنبی صلی اللہ علیہ وسلم پر سب کے لئے رحمت غالب تھی اور خاص کر آپ اپنی امت کے لئے بڑے مہربان تھے لیکن جب جھٹلانے والو ں کو اس وعید کے ذریعہ ڈرایا گیا تو رسول اللہ صلی اللہ علیہ وسلم کے دل میں شفقت ومہربانی جو ش مارنے لگی۔چنانچہ اللہ تعالیٰ نے آپ کو تسلی دیتے ہوئے اور آپ کو ابھارتے ہوئےآپ کے دل کو مضبوط کیاکہ اگر انہیں کوئی مصیبت لاحق ہوتو ان پر کوئی غم نہ کریں۔ (ابن عاشور: ۲۰؍۲۶)\nرسول اللہ صلی اللہ علیہ وسلم کی رحمت وشفقت تمام مخلوق کے لئے تھی۔ آیت کریمہ اس بات پر کیسے دلالت کرتی ہے؟\nقُلۡ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعۡضُ ٱلَّذِي تَسۡتَعۡجِلُونَ ٧٢ وَإِنَّ رَبَّكَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ ٧٣\nیہ خبر نبی صلی اللہ علیہ وسلم کے ساتھ خا ص ہے جس میں اس بات کی تنبیہ ہے کہ عذاب میں تاخیر ہونا اللہ کی رحمت کا نتیجہ ہے کیونکہ تاخیر اللہ کی جانب سے ڈھیل ہے، اور اس مدت میں وہ نعمتوں میں ہوتے ہیں۔ (ابن عاشور: ۲۰؍۲۸)\nعذاب میں تاخیر اللہ کی رحمت کا نتیجہ ہے۔ اس کو واضح کیجئے.\nوَإِنَّ رَبَّكَ لَيَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ ٧٤\nآیت میں اس بات کی طرف اشارہ ہے کہ ان کے اور بہت سے قبیح اعمال ایسے ہیں جنہیں بیان نہیں کیا جاسکتا۔ آیت کے اندر سینہ میں چھپانے کی بات کو مقدم کیا گیا تاکہ واضح طور پر یہ پتہ چل جائے کہ اللہ تعالیٰ کے نزدیک پوشیدہ اور ظاہر سب برابر ہے۔یا اس لئے کہ دلوں میں پوشیدہ چیزیں اعضاء وجوارح سے صادر ہونے والی چیزوں کا سبب ہوتی ہیں۔ (الالوسی: ۱۰؍۲۲۸)\nسینوں کے اندر چھپی ہوئی چیزوں کے علم کو ظاہری چیزوں کے علم پر مقدم کرنے کا کیا فائدہ ہے؟نیز آیت کریمہ سے قلبی اعمال کی اہمیت پر کیسے استدلال کرسکتے ہیں؟\nإِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَقُصُّ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَكۡثَرَ ٱلَّذِي هُمۡ فِيهِ يَخۡتَلِفُونَ ٧٦\nمطلب یہ ہے کہ بیشک یہ قرآن ان کے مختلف فیہ مسائل کو واضح کرتا ہے اگر وہ اس پر عمل کریں۔ (القرطبی: ۱۶؍۲۰۴)\nکسی مسئلہ میں اگر ہمارا اختلاف ہوجائے تو اس سے نکلنے کا راستہ کہاں ملے گا؟\nwords\nوَمَا يَشعُرُوناور وه جانتے نهيں.\nأَيَّانَكب.\nادَّارَكَان كا علم ختم هوگيا؛ اور اس كے وقت كي معرفت سے عاجز آگئے.\nعَمُونَاس كو ديكھنے سے ان كي آنكھيں اندھي هيں.\nأَسَاطِيرُ الأَوَّلِينَپهلے لوگوں كي تحريركرده جھوٹي كهانياں.\nرَدِفَ لَكُمتمهارے قريب هے.\nتُكِنُّوه چھپاتے هيں ."],[384,"§النمل\ndeeds\nاللہ سے دعا کیجئے کہ قرآن کریم کو آپ کے حق میں دلیل اور رحمت بنادے.\nکوئی وعظ یا درس سنئے اور جو سنئے اس پر عمل کیجئے.\nایک رات جلدی سوجائیے اور اگلی رات دیر سے سوئیے پھر اپنے ذہن پر، اپنی صحت پر، اپنے معمولات پر اور اپنی عبادت پر ان دونوں راتوں کے فرق کو محسوس کیجئے.\nguid\nلوگوں کی ہدایت اور ان پر رحمت قرآن کا مقصد ہے.\nآج لوگوں کے بیچ جو بھی اختلافات ہیں بیشک اللہ قیامت کے دن انصاف کے ساتھ ان کا فیصلہ کریگا.\nایک مسلمان اور طالب علم پر یہ واجب ہے کہ جس مسئلہ کا اسے علم نہ ہو اس میں اس وقت تک توقف اختیار کرے جب تک وہ مسئلہ اس کے لئے واضح نہ ہوجائے لہذا وہ بلا علم بات نہ کرے.\nrefl\nوَإِنَّهُۥ لَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ٧٧\nجہاں تک قرآن کے ا ن کے لئے رحمت ہونے کی بات ہے تو اس لئے کہ جب اس کے ذریعہ انہیں ہدایت مل گئی توانہوں نے اپنی اصلاح کرکے،اپنے اعمال کو درست کرکے اور متحد ہوکر دنیا کے اندر کامیابی حاصل کرلی اور جنت پاکر آخرت میں بھی کامیاب ہوگئے۔ (ابن عاشور: ۲۰؍۳۱)\nقرآن کریم مومنوں کے لئے رحمت کیسے ہے؟\nوَإِنَّهُۥ لَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ٧٧\nقرآن سارے عالم کے لئے رحمت ہے،پھر بھی خصوصیت سے مومنوں کا ذکر کیا گیا اس لئے کہ یہی اس سے حقیقی فائدہ اٹھاتے ہیں۔ (الالوسی: ۱۰؍۲۲۹)\nقرآن سارے عالم کے لئے رحمت ہے پھر خصوصیت سے مومنوں کا ذکر کیوں کیا گیا؟\nفَتَوَكَّلۡ عَلَى ٱللَّهِۖ إِنَّكَ عَلَى ٱلۡحَقِّ ٱلۡمُبِينِ ٧٩\n(إنك على الحق المبين) یعنی بہت ہی واضح ہے اور جو واضح حق پر ہوگا اس کی طرف لوگوں کو بلائیگا،ان کی ہمیشہ مدد کریگا اور دوسروں کے مقابلہ میں زیادہ بھروسہ کرنے والا ہوگا کیونکہ وہ ایسی چیز کے لئے کوشش کررہا ہوتا ہے جو امر یقینی ہے جس کی سچائی معلوم ہے اور جس کے اندر کسی شک وشبہ کی کوئی گنجائش نہیں ہے۔ (السعدی؍۶۰۹)\nواضح حق پر نبی صلی اللہ علیہ وسلم کے بھروسہ کرنے کا کیا تعلق ہے؟\nإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ مُدۡبِرِينَ ٨٠\nبیشک آپ مُردوں کو نہیں سناسکتے یعنی ان کفار کو جو نصیحتوں کو قبول کرنے میں بہروں جیسے ہیں چنانچہ جب انہیں کسی خیر وبھلائی کی طرف بلایاجاتاہے تو وہ انکار کرکے منہ پھیرلیتے ہیں۔ایسا لگتا ہے کہ سنتے ہی نہیں۔ (القرطبی: ۱۶؍۲۰۵)\nکافروں کو مُردوں اور بہروں سے تشبیہ کیوں دی گئی؟\nوَوَقَعَ ٱلۡقَوۡلُ عَلَيۡهِم بِمَا ظَلَمُواْ فَهُمۡ لَا يَنطِقُونَ ٨٥\nامام قتادہ رحمہ اللہ نے فرمایا: وہ کیسے بول سکتے ہیں جبکہ ان کے پاس کوئی دلیل نہیں ہے! (البغوی: ۳؍ ۴۱۸)\nوہ کیوں نہیں بول سکتے؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٨٦\nیعنی میں نے یہ فیصلہ کردیا کہ ان کا ایمان تازہ ہوتا رہیگا چنانچہ روزانہ ان کے ایمان کے درجات بلند ہوتے رہتے ہیں۔ (البقاعی: ۱۴؍۲۲۲)\nاس لفظ(يؤمنون)کو مضارع (زمانہ حال ومستقبل پر دلالت کرنے والے صیغہ)کے ساتھ لانے کا کیا فائدہ ہے؟\nصُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ إِنَّهُۥ خَبِيرُۢ بِمَا تَفۡعَلُونَ ٨٨\nاللہ نے جو بھی پیدا کیا اس میں کچھ نہ کچھ حکمت ضرور ہے جیسا کہ فرمایا: (صُنع الله الذي أتقن كل شيء)کی کاریگری ہے جس نے ہر چیز کو بڑی مضبوطی سے بنایاہے۔ اور فرمایا: ﴿ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥ﴾(سورۂ سجدہ: ۷)اللہ نے جو بھی پیدا فرمایا اسے خوبصورت انداز میں پیدا فرمایا۔ اللہ تعالیٰ سارے عالم سے بےنیاز ہے۔اس طور پر یہاں حکمت دوچیزوں کو شامل ہے۔اول: ایسی حکمت جس کا تعلق اس کی ذا ت سے ہے جسے وہ چاہتا اور اس سے وہ خوش ہوتاہے۔دوم: ایسی حکمت جس کا تعلق اس کے بندوں سے ہے۔ یہ ان پر نعمت ہے جس پر وہ خوش ہوتے ہیں اور لذت حاصل کرتے ہیں۔ (ابن تیمیہ: ۵؍۶۸)\nاللہ نے جو بھی پیدا کیا اس میں کوئی نہ کوئی حکمت ہے۔ اللہ کی حکمت کن چیزوں کو شامل ہے؟\nwords\nوَلَّوا مُدبِرِينَوه آپ سے منه موڑ گئے.\nفَوجًاجماعت.\nيُوزَعُونَانهيں روكا جائے گا؛ پهلے جھوٹے سے آخري تك ؛ پھر سب كو حساب كے ليے لايا جائے گا.\nدَاخِرِينَذليل و حقير / بونے.\nجَامِدَةًاستقرار پكڑے هوئے /ركے هوئے.\nتَمُرُّوه چلتے هيں۔ /گزرتے هيں."],[385,"§النمل ، القصص\ndeeds\nکوئی نیک کام کیجئے اور اللہ سے دعا کیجئے کہ آپ کے اجر میں اضافہ فرمائے.\nقرآن کریم کی کوئی سورت اچھی طرح غوروفکر کے ساتھ سمجھ کر پڑھئے.\nیہ دعا مانگئے: “اَللّٰهُمَّ أَرِنِيْ الْحَقَّ حَقًّا وَارْزُقْنِيْ اتِّبَاعَهُ واَرِنِيْ الْبَاطِلَ بَاطِلًا وَارْزُقْنِيْ اجْتِنَابَهُ”۔اے اللہ! مجھے حق کو حق کی شکل میں دکھا اور اس کی اتباع کی توفیق دے اور باطل کو باطل کی صورت میں دکھا او ر اس سے بچنے کی توفیق دے.\nguid\nجس قدر آپ کی نیکیاں ہوں گی اسی قدر قیامت کے دن کی گھبراہٹ سے آپ مامون رہ سکیں گے.\nجب اللہ تعالیٰ کسی بندے کو ہدایت دینا چاہتا ہے تو اس کے لئے صرف قرآن کریم کو سن لیناہی کافی ہوجاتا ہے.\nاللہ کا قانون ہے کہ جب ظالم لوگ اصلاح پسندوں پر سرکشی کرنے یا ان میں تفرقہ ڈالنے یا انہیں کمزور کرنے یا قتل کرنے کی کوشش کرنے لگتے ہیں تو اللہ انہیں ہلاک کردیتا ہے.\nrefl\nمَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَا وَهُم مِّن فَزَعٖ يَوۡمَئِذٍ ءَامِنُونَ ٨٩\n(فله خير منها) یعنی اس سے بہتر ہوگا۔یعنی اللہ کا ثواب بندے کے عمل اور اس کے قول وذکر سے زیادہ بہتر ہے اور اسی طرح اللہ کی خوشنودی بندے کے لئے اس کے عمل سے بہتر ہے۔ اور کہا گیا ہے کہ اس کا تعلق ثواب کے کئی گنابڑھنے سے ہے کیونکہ اللہ تعالیٰ ایک عمل کے بدلہ دس نیکیاں دیتاہے اور ایمان کے بدلہ تھوڑی سی مدت میں ہمیشگی کے ثواب سے نوازتا ہے۔ (القرطبی: ۱۶؍۲۲۴)\nآیت کے اس جملہ (فله خير منها) کا کیا مطلب ہے؟\nوَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ\n(وأن أتلو القرآن) اور یہ کہ میں قرآن کی تلاوت کرتا رہوں یعنی لوگوں کو برابر پڑھ پڑھ کر سناتا رہوں۔ تاکہ دعوت دین باربار ہوتی رہے اور ساتھ ہی لوگوں کی رہنمائی بھی ہوتی رہے کیونکہ راہ حق کی طرف رہنمائی میں یہ کافی ہے۔ اور یہ بھی کہا گیا ہے کہ: میں قرآن کو برابر پڑھتا رہوں تاکہ آہستہ آہستہ میرے لئے اس کے اندر چھپے عمدہ حقائق اور علمی خزانے ظاہر ہوجائیں۔ (الالوسی: ۱۰؍۲۴۸)\nقرآن کریم کو پابندی سے پڑھنے کا کیا اثر ہوتاہے؟\nوَمَن ضَلَّ فَقُلۡ إِنَّمَآ أَنَا۠ مِنَ ٱلۡمُنذِرِينَ ٩٢\nیعنی میرے لئے وہ رسول نمونہ ہیں جنہوں نے اپنی قوموں کو ڈرایا، نبوت ورسالت کے پیغام کو کما حقہ ان تک پہنچایا اور اپنی ذمہ داری کو اخلاص سے نبھایا اور اب ان قوموں کا حساب وکتاب اللہ کے ذمہ ہے۔ (ابن کثیر: ۳؍۳۶۶)\nگمراہ لوگوں کے تئیں ڈرانے والے رسولوں کی کیا ذمہ داری ہے؟\nنَتۡلُواْ عَلَيۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمٖ يُؤۡمِنُونَ ٣\nاس میں ایمان والوں کو ہی خطاب کیا گیا ہے اور کلام کا رخ بھی انہی کی طرف ہے کیونکہ انہی کے پاس ایمان ہے جس کی بناپر وہ اس میں تدبر کرتے ہیں، اسے قبول کرتے ہیں اور عبرت کے مواقع پر اس سے رہنمائی حاصل کرتے ہیں اور اس کے ذریعہ سے ان کے ایمان ویقین میں اضافہ ہوتاہے اور ان کی نیکیاں نشوونما پاتی ہیں۔ رہے ان کے علاوہ دیگر لوگ تو وہ اس سے استفادہ نہیں کرسکتے سوائے یہ کہ ان پر حجت قائم ہو۔اللہ تعالیٰ نے اس کو ان سے محفوظ کردیا ہے اور اپنے اور ان کے درمیان پردہ حائل کردیا ہے جس کی وجہ سے وہ اس کو سمجھنے سے عاجز ہیں۔ (السعدی؍ ۶۱۱)\nموسیٰ علیہ السلام اور فرعون کے قصہ کو مومنوں کے ساتھ کیوں خاص کیا گیا ہے؟\nإِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ\n(إن فرعون علا في الأرض) کہہ کر دنیا کے اندر فرعون کے مقام ومرتبہ کو بلند کرکے پیش کیا گیا تاکہ مرنے کے بعد اسی طرح لوگوں کے لئے عبرت کی بڑی نشانی بنے۔(ابن عاشور: ۲۰؍۶۶)\n(إن فرعون علا في الأرض)کہہ کر دنیا میں فرعون کے تکبر اور اس کے مقام ومرتبہ کو بلند کرکے کیوں پیش کیا گیاہے؟\nإِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا\n(وجعل أهلها شيعًا) یعنی انہیں گروہوں میں بانٹ دیا اور ہر گروہ کے پاس کچھ نہ کچھ ہوتا جس کی وہ حمایت کرتا اور سارے گروہ فرعون کے ماتحت اور اس کی اطاعت میں ہوتے۔گویا سارے گروہ ایندھن کی لکڑیوں کی مانند اکٹھافرعون کے ساتھ ہوتے۔ فرعون نے انہیں گروہوں میں بانٹ دیا تاکہ ایک ساتھ مل کر اس کے خلاف سازش نہ کرسکیں اور اس کے خلاف اپنے کسی مقصد میں کامیاب نہ ہوسکیں ۔اس طرح ان کا اتحاد پارہ پارہ ہوجائیگا اور کوئی دوسرے کی حمایت نہ کرسکے گا اور اس طرح آپس میں ذلیل ہوکر ان کا معاملہ کمزور پڑجائیگا۔ (البقاعی: ۱۴؍ ۱۴۰)\nاتحاد واتفاق کی صف کو توڑنا ہمیشہ دشمنوں کے اہم مقاصد میں سے ہوتا ہے۔اس اختلاف سے امت کی قوت پر کیا اثر پڑتا ہے؟\nيُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ ٤\nوہ بنواسرائیل کے نوزائیدہ لڑکوں کو اس لئے ذبح کروادیتا تھا کیونکہ کاہنوں نے اس سے کہا تھا کہ بنواسرائیل میں ایک لڑکا پیدا ہوگا جس کے ہاتھوں تمہاری بادشاہت ختم ہوجائیگی۔یا ایسا کرنے کے لئے اسے نجومیوں نے کہا تھا۔ یا یہ کہ اس نے ایک خواب دیکھا تھا جس کی تعبیر اس طرح پیش کی گئی۔ امام زَجّاج رحمہ اللہ نے کہا: اس کی حماقت پر تعجب ہے!اسے نہیں معلوم کہ اگر کاہن سچا بھی ہو تو بھی قتل کچھ فائدہ مند نہیں ہوسکتا اور اگر جھوٹا ہو تو قتل کا کوئی مطلب نہیں رہ جاتا۔ (القرطبی: ۱۶؍۲۳۰)\nفرعون کی حماقت کس قدر بڑھی ہوئی تھی اس کی وضاحت کیجئے؟\nwords\nبِالحَسَنَةِتوحيد و ايمان او رعبادت كے ساتھ.\nبِالسَّيِّئَةِشرك اور كفر كے ساتھ.\nحَرَّمَهَااسے حرمت والا قرار ديا/ وهاں پر خون بهانا ؛ شكار كرنا درخت كاٹنا ممنوع ٹھهرا.\nعَلاَتكبر اور سركشي كي.\nشِيَعًامتفرق گروه.\nنَمُنَّهم فضل /احسان كرتے هيں."],[386,"§القصص\ndeeds\nجس خاندان کے کسی فرد پر ظلم ہوا ہو تو انہیں خصوصی پیغام بھیج کر اس آیت کے ذریعہ خوشخبری دیجئے.\nاللہ تعالیٰ سے دعا کیجئے کہ آپ کی بیوی او ر اولاد کو آپ کی آنکھوں کی ٹھنڈک بنادے.\nاللہ تعالیٰ سے سوال کیجئے کہ آپ کے دل کو مضبوط کردے اور تنگی وآسانی میں آپ کو ثابت قدم رکھے.\nguid\nزمین پر غلبہ حاصل کرنے کے لئے صبر،تیاری اور اس کی خاطر کوشش کرنا ضروری ہے.\nبعض دفعہ نعمتیں تکلیفوں کے ساتھ ہی آتی ہیں جیسے کہ اللہ تعالیٰ موسیٰ علیہ السلام کی والدہ سے ان کی تکلیف کے موقع پر وعدہ کررہا ہے کہ انہیں راحت حاصل ہوگی اور ساتھ ہی عظیم فضل بھی ملے گا وہ اس طرح کہ اللہ ان کے بیٹے کو نبی بنائیگا.\nمصیبتوں پر صبر کرنا اللہ کا فضل واحسان ہے لہذا اللہ سے اس کا فضل مانگئے.\nrefl\nوَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ ٧\nاللہ تعالیٰ نے اس آیت میں یہ بیان کیا ہے کہ وہ مومنوں کو ایمان نیز ہر اس چیز سے نوازتا ہے جو ان کے لئے نفع بخش ہے اور یہ مومنوں کی طرف وحی ہوتی ہے گرچہ وہ انبیاء نہیں ہیں۔ (ابن تیمیہ: ۵؍۷۰)\nآیت کریمہ نے مومنوں پر اللہ کے فضل کو واضح کیا ہے۔وہ کیا ہے؟\nوَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إلى قوله تعالى وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ\nبندے کو اگر یہ پختہ علم ہوجائے کہ قضا وقدر اور اللہ کا اٹل فیصلہ نافذہوکر رہتا ہے تو وہ ان اسباب کے اپنانے میں کبھی دیر اور سستی نہیں کریگا جن کا اسے حکم دیا گیا ہے اور یہ چیز اللہ کی قضاء و قدر پر ایمان کے منافی بھی نہیں ہے کیونکہ اللہ تعالیٰ نے موسیٰ علیہ السلام کی والدہ سے وعدہ کیا تھا کہ بچے کو ان کے پاس واپس لوٹادیگا۔اس کے باوجود بچے کی واپسی کے لئے انہوں نے پوری کوشش کی اور اس کے لئے اپنی بیٹی یعنی موسیٰ علیہ السلام کی بہن کو پیچھے لگا دیا تاکہ اس پر نظر رکھے۔(السعدی؍۶۱۹)\nموسیٰ علیہ السلام کی والدہ نے ان کی بہن کو موسیٰ علیہ السلام کی بابت معلومات حاصل کرنے کے لئے پیچھے بھیجا۔تو کیا اللہ کے وعدے کے ہوتے ہوئے یہ ایمان کے منافی ہے؟\nوَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ ٧\nاللہ تعالیٰ نے موسیٰ علیہ السلام کی ماں کو دودھ پلانے کا حکم دیا تاکہ ماں کے دودھ سے ان کا جسم(بنیادی ڈھانچہ)مضبوط ہوسکے۔اور دریا میں ڈالنے سے پہلے آخری مرتبہ بھی ماں کا دودھ پی لیں تاکہ وہ دریا میں ڈالنے سے آل ِفرعون کے اٹھانے تک خوراک کا کام کرتارہے یہاں تک کہ آپ فرعون کے محل میں پہنچ جائیں۔ (ابن عاشور: ۲۰؍۷۳)\nدریا میں ڈالنے سے پہلے موسیٰ علیہ السلام کی ماں کو دودھ پلانے کا حکم کیوں دیا گیا؟\nوَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ ٩\nفسادیوں اور فتنہ پرور لوگوں کے بیچ میں نیک لوگوں کے وجود سے فسادیوں کا فساد کچھ نہ کچھ کمزور پڑجاتا ہے۔اس کی دلیل یہ ہے کہ فرعون کی بیوی اس بچے (موسیٰ ) کے قتل میں رکاوٹ بنی تھی حالانکہ فرعون کو معلوم تھا کہ یہ اسرائیلی بچہ ہے۔ (ابن عاشور: ۲۰؍۸۶)\nفسادیوں کے بیچ میں نیک لوگوں کا وجود فساد میں کمی کا باعث ہوتا ہے۔واضح کیجئے.\nعَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا\nاللہ تبارک وتعالیٰ نے مقدر فرمادیا کہ وہ بچہ فرعون کی بیوی کو فائدہ پہنچائے جس نے یہ بات کہی تھی چنانچہ جب وہ بچہ فرعون کی بیوی کی آنکھوں کی ٹھنڈک بن گیا، اسے اس بچہ سے شدید محبت ہوگئی اور وہ بچہ اس کے لئے حقیقی بیٹے کی حیثیت اختیار کرگیا یہاں تک کہ وہ بڑاہوگیا اور اللہ تعالیٰ نے اس کو نبوت ورسالت سے سرفراز کردیا تو اس نیک عورت نے فوراًاسلام قبول کرلیا۔ رضی اللہ عنہا وأرضاھا۔ (السعدی؍۶۱۲)\nکیاموسیٰ علیہ السلام پر شفقت ومہربانی کرنے کی وجہ سے فرعون کی بیوی کو فائدہ ہوا؟\nوَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ١٠\nبندہ اگر مصیبت میں پڑے اور صبر کرکے جما رہے تو اس کے ایمان میں اضافہ ہوتا ہے۔اس سے اس بات کا پتہ چلتا ہے کہ مصیبت میں ہائے وائے کرنا کمزور ایمان کی پہچان ہے۔ (السعدی؍۶۱۳)\nہائے واویلاکرنے سے ایمان کے گھٹنے بڑھنے کا کیا تعلق ہے؟\nوَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ١٠\nاس کا ایک مطلب یہ بتایا گیا ہے کہ موسیٰ علیہ السلام کی ماں کے دل میں موسیٰ کی یاد کے سواکوئی خیال باقی نہ رہا۔ (ابن تیمیہ: ۱۰؍۲۱۹)\nاولاد کے لئے ماں کی محبت بہت زیادہ ہوتی ہے۔آیت کی روشنی میں اس کی وضاحت کیجئے.\nwords\nاليَمِّنهر/ مراد دريائے نيل هے.\nقُرَّةُ عَينٍ لِيميري خوشي كا مصدر.\nفَارِغًاحضرت موسي كے خيال كے علاوه هر چيز سے خالي.\nلَتُبدِي بِهِوه صراحت كے ساتھ كهه دے كه يه ميرا بيٹا هے.\nيَكفُلُونَهُ لَكُمجو اس كي تربيت و رضاعت كي ذمه داري نبھائيں گے."],[387,"§القصص\ndeeds\nدوجھگڑنے والوں کے درمیان صلح کرائیے.\nاپنے کسی گناہ کو یاد کرکے اللہ سے استغفار کیجئے او ر یہ دعا پڑھئے: “رَبِّ إِنِّيْ ظَلَمْتُ نَفْسِيْ فَاغْفِرْ لِيْ”۔میرے رب! میں نے خود اپنی ذات پر ظلم کرلیاہے،تو مجھے بخش دے.\nکسی ایسے نیک آدمی کا دفاع کیجئے جس کے خلاف اخبارات یا جرائد یا انٹرنیٹ پر افواہ پھیلائی جاتی ہو.\nguid\nاچھے انداز سے عبادت کیجئے یقینا ًاللہ آپ کو حکمت اور علم سے نوازیگا.\nشیطان سے خبردار رہئے،بیشک وہ انسانوں کا دشمن اور انہیں گمراہ کرنے والا ہے.\nلوگوں کے لئے اپنا تعاون پیش کرنا اور ان کی خیر خواہی کرنا مثبت عمل ہے.\nrefl\nوَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ١٤\n(وكذلك نجزي المحسنين)یعنی اچھی طرح اللہ تعالیٰ کی عبادت کرنے والوں اور اللہ کی مخلوق کے ساتھ احسان کرنے والوں کو ہم اسی طرح بدلہ بھی اچھا دیتے ہیں۔ چنانچہ اللہ تعالیٰ ان کے احسان کے مطابق انہیں علم وحکمت سے سرفراز فرماتا ہے۔ تویہ آیت کریمہ موسیٰ علیہ السلام کے کمال احسان پر دلالت کرتی ہے۔ (السعدی؍۶۱۳)\nآیت کریمہ سے پتہ چلتا ہے کہ احسان کا بدلہ عظیم ترین ہوتا ہے۔ اس کا سبب واضح کریں.\nقَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ ١٥\nیہ اس بات کی دلیل ہے کہ نفس ِانسانی میں اصل چیزخیر ہے اور یہی فطرت ہے۔اس سے منحرف ہونے کے لئے غیر فطری سبب کا ہوناضروری ہے اور وہ سبب نفس ِانسانی کے اندر شیطان کا کچوکا لگاکر مداخلت کرنا ہے۔ (ابن عاشور: ۲۰؍۹۰)\nآیت کریمہ کی روشنی میں بتائیے کہ نفس ِانسانی میں اصل کیا ہے؟\nوَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ ١٥\n(فقضى عليه) یعنی اسے قتل کردیا، دراصل موسیٰ علیہ السلام اس قبطی کو قتل کرنے کا ارادہ نہیں رکھتے تھے لیکن آپ کے گھونسہ سے اتفاقاً اس کی موت ہوگئی اس وجہ سے آپ اس پر شرمندہ ہوئے اور یہ سمجھا کہ ان کے ہاتھ میں شیطان کا کچوکا شامل تھا اور اس گھونسہ میں جو غضبناکی شامل تھی وہ شیطان کے وسوسہ کا نتیجہ تھی اور موسیٰ علیہ السلام نے اس بات کی صراحت بھی کردی اور اسے شیطان کا عمل قرار دیا ہے۔غصے کی حالت میں موسیٰ علیہ السلام کے گھونسے میں ان کے ارادے سے زیادہ قوت آگئی تھی۔ (ابن عطیہ: ۴؍ ۲۸۰)\nقبطی کو موسیٰ علیہ السلام نے خود قتل کیا۔لیکن ا س قتل کی نسبت شیطان کی طرف کیوں کی؟\nقَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ\nموسیٰ علیہ السلام نے اپنے نفس پر جو ظلم کیا تھا اس کا اعتراف کرلیا اور وہ کسی انسان پر ایسی زیادتی تھی جس کی آپ کو اجازت نہیں تھی۔ (ابن تیمیہ: ۵؍۷۱)\nحق کا اعتراف انبیاء کی صفت ہے۔اس کی وضاحت کیجئے.\nقَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ١٦\nپھر موسیٰ علیہ السلام نے اعتراف کیا اور گناہ کی معافی مانگ لی اور اللہ نے معاف بھی کردیا۔ اگر یہ اعتراض کیا جائے کہ ایسے قتل پر کیسی مغفرت جب مقتول کافر ہو؟تو اس کا جواب یہی ہوگا کہ آپ کو اس کے قتل کی اجازت نہیں تھی۔یہی وجہ ہے کہ موسیٰ علیہ السلام قیامت کے دن کہیں گے کہ:میں نے ایسے شخص کو قتل کردیا جس کی مجھے اجازت نہیں تھی۔ (ابن جزی: ۲؍ ۱۴۱)\nموسیٰ علیہ السلام نے ایک کافر کے قتل پر مغفرت کیوں مانگی؟\nقَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ١٦\nموسیٰ علیہ السلام گھونسہ مارنے پر بہت شرمندہ ہوئے جس سے ایک شخص کی جان چلی گئی۔اسی شرمندگی نے آپ کو اپنے رب سے گڑگڑانے اور اس گناہ سے معافی مانگنے پر ابھارا۔امام قتادہ رحمہ اللہ نے کہا: اللہ کی قسم! موسیٰ علیہ السلام نے اس گناہ سے نکلنے کا راستہ معلوم کرکے استغفار کرلیا۔پھر برابر آپ اس کو اپنے نفس پر گناہ شمار کرتے رہے،حالانکہ آپ کو اس کی مغفرت کا علم تھا۔یہاں تک کہ آپ قیامت کے دن بھی کہیں گے کہ میں نے ایک ایسی جان لے لی جس کی مجھے اجازت نہیں تھی۔ اس طرح آپ نے اپنے لئے اسے گناہ سمجھا اور کہا: (ظلمت نفسي فاغفر لي ) یعنی میں نے اپنے اوپر ظلم کیا ہے تو مجھے معاف فرمادے۔ کیونکہ کسی نبی کے لئے مناسب نہیں ہے کہ وہ اللہ کی اجازت کے بغیر کسی کو قتل کردیں۔اوراس لئے بھی کہ انبیاء اس قدر شفیق اور مہربان ہوتے ہیں جتنا کوئی دوسرا نہیں ہوتا۔ (القرطبی: ۱۶؍ ۲۴۷-۲۴۸)\nموسیٰ علیہ السلام نے قبطی کو قتل کرکے اپنے آپ کو گناہگار کیوں سمجھا؟\nقَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ ١٧\n(الظهير) مددگار کو کہتے ہیں (بِمَاۤ)میں “ب” سبب بیان کرنے کے لئے آیا ہے۔مطلب یہ ہے کہ تیرے احسان کی وجہ سے میں مجرموں کا کبھی مددگار نہیں بنوں گا۔یہ ایک عہد تھا جو موسیٰ علیہ السلام نے اپنے رب سے کیا تھا۔ (ابن جُزی: ۲؍ ۱۴۰)\nمومن پر اس وقت کیا واجب ہوتا ہے جب اس سے کوئی گناہ سرزد ہوجانے کے بعد اللہ کی طرف سے اپنے اوپر احسان اور ستر پوشی کی نعمت دیکھے؟\nwords\nمِن شِيعَتِهِاسي كے گروه سے۔مراد قوم موسي ؛ بني اسرائيل هيں.\nفَوَكَزَهُاسے مكا مارا.\nيَتَرَقَّبُاس كے برائي ميں پڑنے كي توقع كرتا تھا.\nيَستَصرِخُهُوه اس سے مدد مانگ رها تھا.\nلَغَوِيٌّبهت سركش/ زياده گمراه."],[388,"§القصص\ndeeds\nکسی کمزور کے لئے دست تعاون دراز کرکے اس کی مدد کیجئے.\nجو خواتین اپنے پردہ کی پرواہ نہیں کرتیں انہیں کسی پیغام کے ذریعہ نصیحت کیجئے او ر بتائیے کہ حیاء ہمیشہ سے مومنہ عورتوں کا شعار رہی ہے.\nجس نے آپ کے ساتھ بھلائی کی ہو اسے اس کا اچھا بدلہ دیجئے کہ یہی صالحین کی عادت ہے.\nguid\nحیاء خواتین کے لئے فضیلت ہے اور وہ مومنہ عورتیں یقینا ًشرف والی ہیں جو مردوں کے ساتھ میل جول سے دوررہتی ہیں.\nکمزوروں کا خیال رکھنااور ان کی خدمت کرنا انبیاء کے اخلاق اور عمدہ سیرت کا حصہ ہے.\nقبولیت دعا کے اسباب میں سے ہے کہ بندہ گڑگڑائے اور اپنی عاجزی وبے بسی کا اظہار کرے جیسا کہ موسیٰ علیہ السلام نے کیا تھا.\nrefl\nقَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ ٢٣\n(قالتا لا نسقي حتى يصدر الرعاء) یعنی ہم عورتیں ہیں،مردو ں کی بھیڑ میں نہیں جاسکتیں۔(وأبونا شيخ كبير) یعنی وہ اس قدر بوڑھے ہیں کہ یہ کام خود نہیں کرسکتے،چوپایوں کو پانی نہیں پلاسکتے ہیں۔ چنانچہ مجبوراً ہم دونوں لوگوں کے فارغ ہونے کا انتظار کرتی ہیں پھر اس کے بعد پانی پلاکر واپس گھرجاتی ہیں۔ (الطبری: ۱۹؍۵۵۴)\nآیت سے پتہ چلا کہ مردوزن کے اختلاط کی ممانعت انبیاء کرام علیہم السلام کی سنت ہے۔ اس کی وضاحت کیجئے.\nفَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ ٢٤\nچنانچہ سب سے پہلی چیز جو موسیٰ علیہ السلام کو اللہ کی طرف سے ملی وہ علم وحکمت ہے۔اور اللہ کی جانب سے موسیٰ علیہ السلام کو ملنے والی بھلائیوں میں سے ان کا قتل سے نجات پانا، بادشاہت کی پرتعیش نعمتوں میں مکمل تربیت پانا اور عزت حاصل کرنا ہے۔اور فرعونی خاندان کے عقائد باطلہ سے آپ کا محفوظ رہنا ہے۔چنانچہ آپ نے اس کی منفعتوں سے فائدہ اٹھایا اور اس کی رذالتوں اور نقصانات سے اپنے آپ کو بچائے رکھا۔ انہی بھلائیوں میں سے ایک یہ بھی ہے کہ اللہ تعالیٰ نے آپ کی قوم کو آپ کے ذریعہ غلبہ عطاکیا اور یہ کہ دوبارہ آپ کو ناحق قتل سے نجات دلائی اور اس محفوظ جگہ تک آپ کی رہنمائی فرمائی جہاں ایک نبوی گھرانے سے آپ کا تعارف ہوا۔ (ابن عاشور: ۲۰؍۱۰۲)\nخیر کی تین ایسی صورتیں ذکر کیجئے جن سے اللہ تعالیٰ نے موسیٰ علیہ السلام کو نوازا تھا؟\nفَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ\nگویا حیاء ان کے لئے ایسی سواری تھی جس پر وہ پوری طاقت سے سوار تھیں اور اس کی باگ کی مالک تھیں اسی لئے حرف استعلاء(فوقیت)سے تعبیر کیا اور (على استحياء) فرمایا۔یعنی حیاءکا وجود ان کی ذات میں ہے کیونکہ انہیں ایک اجنبی شخص کے پاس جاکر بات کرنے اور اس کے ساتھ چلنے کا مکلف بنایا گیا۔ (البقاعی: ۱۴؍۲۶۸)\nحیا اس خاتون کے ایک نیک آدمی سے شادی کرنے کا سبب بن گئی۔ آیت کی روشنی میں اس کی وضاحت کیجئے.\nقَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ ٢٦\n(استأجره)یعنی اسے اپنے پاس بطور مزدور رکھ لیں(إن خير من استأجرت القوي الأمين) یہ کلام بہت ہی جامع،بلیغ اور حکمت سے پر ہے۔ روایات میں ہے کہ:اس خاتون کے والد نے اس سے پوچھا: ان کی طاقت وقوت اور امانت داری کا تمہیں کیسے علم ہوا؟ اس نے جواب دیا: قوت تو میں نے اسی وقت دیکھا جب انہوں نے کنویں کے منہ سے اکیلے ہی پتھر کو ہٹادیا۔اور امانت داری اس وقت دیکھا جب انہوں نے مجھے ایک نظر بھی نہیں دیکھا۔ (ابن جزی: ۲؍ ۱۴۳)\nجس کے ہاتھ میں زمام امر ہے اس کی خیرخواہی کرنی چاہئے۔ اس بات کی مشروعیت آیت کی روشنی میں واضح کیجئے.\nإِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ ٢٦\nیہ دونوں صفات ہر اس شخص میں دیکھی جانی چاہئے جسے کوئی منصب سونپا جائے یا اسے اجرت وغیرہ پر رکھا جائے۔ معاملات میں بگاڑ اسی وقت پیدا ہوتا ہے جب یہ دونوں اوصاف یا ان میں سے ایک صفت مفقود ہو۔جبکہ ان دونوں اوصاف کے اجتماع سے اس کام کی تکمیل بہت اچھی طرح ہوتی ہے۔ (السعدی؍ ۶۱۴)\nآیت سے اس شخص کے لئے عمدہ صفات کا استنباط کیسے کیا جاسکتا ہے جو عام لوگوں کے معاملات کا ذمہ دارہو؟\nوَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ ٢٧\nیعنی صاحبِ مدین نے آپ کو کام میں نرمی اور حسن معاملہ کے ذریعہ رغبت دلائی۔اور یہ آیت کریمہ دلالت کرتی ہے کہ نیک آدمی کے لئے مناسب یہی ہے کہ جہاں تک ممکن ہو حسن ِاخلاق سے کام لے۔ (السعدی؍ ۶۱۵)\nآیت سے کیسے پتہ چل رہا ہے کہ مالکان اور ذمہ داران پربلند اخلاق کا اپنانا واجب ہے؟\nسَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ ٢٧\nاس سے صرف صاحب معاملہ کا تعارف مقصود ہے،تزکیہ نفس نہیں، جو منع ہے اس سے مراد وہ تزکیہ ہے جس کا مقصد فخر اور خودستائی ہو۔لیکن جس کا مقصد دین یا کسی معاملہ سے ہو تو اچھے مقصد کی خاطر ایسا ہوسکتا ہے۔ (ابن عاشور: ۲۰؍۱۰۹)\nکیا شعیب علیہ السلام کی اس بات (وما أريد أن أشق عليك ستجدني إن شاء الله من الصالحين) میں تزکیہ نفس پایا جاتا ہے؟\nwords\nتِلقَاءَ مَديَنَمدين كي سمت.\nسَوَاءَ السَّبِيلِمدين كا مناسب راسته.\nتَذُودَانِوه اپني بكريوں كو پاني سے روك رهي تھيں.\nمَا خَطبُكُمَاتمهارا كيا معامله هے؟\nيُصدِرَ الرِّعَاءُچرواهے اپني بكرياں لے كر پاني سے چلے جائيں.\nتَأجُرَنِيميري ملازمت كريں گے/ ميرے جانور چرانے كے ليے.\nحِجَجٍسال."],[389,"§القصص\ndeeds\nجس طرح موسیٰ علیہ السلام نے اپنا شکوہ اللہ سے کیا تھا آپ بھی ان کی اقتدا کرتے ہوئے اپنے خوف اور اندیشوں کی شکایت صرف اللہ سے کیجئے.\nکسی داعی کی اس کے کسی ایسے معاملے میں مدد کیجئے جس میں اسے مدد درکار ہو.\nدعوتی ذمہ داری ادا کرنے میں اس شخص سے مدد لیجئے جو آپ کی مطلوبہ صفات والا ہو.\nguid\nانبیاء وفادار ہوتے ہیں؛موسیٰ علیہ السلام نے دونوں مدتوں میں سے لمبی مدت یعنی دس سال پورے کئے.\nصالحین کی صفات میں سے یہ ہیں: حصول رزق کے لئے محنت کرنااور دنیوی مشاکل حل کرنے کے لئے حکمت اور صبر کے ساتھ کوشش کرنا.\nدعوت کے کام میں بر محل دلیل اور مناسب مثال پیش کرنے کی کوشش کیجئے.\nrefl\nفَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ٣٠\n(رب العالمين) کی صفت اس بات پر دلالت کرتی ہے کہ تمام مخلوقات اس کے زیرنگیں ہیں اس صفت کے ذکر سے مقصود یہ ہے کہ اس کے ذریعہ رسالت کا بوجھ اٹھانے میں جو سختی ہے،اس کے لئے موسیٰ علیہ السلام کا دل مضبوط ہوجائے۔ (۲۰؍۱۱۲)\nآیت کریمہ میں (رب العالمين) کی صفت کس بات پر دلالت کرتی ہے؟\nوَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ ٣١\nیہ احتمال باقی رہ جاتاہے کہ وہ شخص خوف سے آزادہوکرآئے مگر اسے امر مکروہ سے حفاظت اور امن کی ضمانت حاصل نہ ہواسی لئے فرمایا: (إنك من الآمنين) بیشک آپ امن پانے والوں میں سے ہیں۔ تب خوف ہر لحاظ سے زائل ہوجاتا ہے۔چنانچہ موسیٰ علیہ السلام ہر خوف اور رعب سے آزاد اور مطمئن ہوکر اور اپنے رب کی خبر پر اعتماد کرتے ہوئے آگے آئے۔اس طور پر کہ ان کے ایمان میں اضافہ اوریقین مکمل ہوچکا تھا۔تو یہ ایک معجزہ تھا جس کا اللہ تبارک وتعالیٰ نے فرعون کے پاس جانے سے قبل آپ کو مشاہدہ کروایاتاکہ جب آپ فرعون کے پاس جائیں تویقین کامل کے مقام پر فائز ہوں۔پس اس صورت میں آپ زیادہ جرأت، زیادہ قوت وصلابت کے ساتھ فرعون کے پاس جائیں گے۔ (السعدی؍ ۶۱۵)\nدلوں کا خوف اور ان کا اطمینان اللہ تعالیٰ کے ہاتھ میں ہے۔ آیت کی روشنی میں اس کی وضاحت کیجئے.\nوَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ٣٤\nمطلق کسی اور کی تائید نہ مانگ کر موسیٰ علیہ السلام نے اپنے بھائی ہارون علیہ السلام کی تعیین کردی کیونکہ آپ کو ان کی امانت داری کا علم تھا۔آپ کو اچھی طرح پتہ تھا کہ وہ اللہ تعالیٰ کے لئے اور خود آپ کے لئے کتنے مخلص تھے اور ساتھ ہی آپ ان کی زبان کی فصاحت سے بھی واقف تھے۔ (ابن عاشور: ۲۰؍۱۱۶)\nانبیاء کرام علیہم السلام کی یہ سنت رہی ہے کہ وہ دعوت کے میدان میں ہمیشہ ساتھ رہنے والے ایسے ساتھی کے حریص رہے ہیں جو مناسب صفات کا حامل ہو۔ آیت کی روشنی میں اس کی وضاحت کیجئے.\nوَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ٣٤\n(فأرسله معي ردءًا) اس کو میرے ساتھ مددگار بناکر بھیج دیجئے تاکہ میرا معاون ہوسکے۔ (يصدقني) جو میری تصدیق کرے۔ کیونکہ خبروں کی تصدیق میں ایک دوسرے کی موافقت کرنا حق کو طاقتور بنادیتاہے۔ چنانچہ اللہ تعالیٰ نے آپ کی مانگ پوری کرتے ہوئے فرمایا: (سنشد عضدك بأخيك) یعنی ہم آپ کے بھائی کے ذریعہ آپ کی مدد کریں گے اور آپ کو طاقت وقوت عطاکریں گے۔ (السعدی؍ ۶۱۵)\nجو دعوت کی ذمہ داری ادا کرنے میں سچا ہوگا وہ اپنی کمی کو پورا کرنے کے لئے دوسرے وسائل بھی اپنانے کی کوشش کریگا۔ آیت کی روشنی میں اس کی وضاحت کیجئے....\nقَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ\nبعض سلف کا کہنا ہے: دنیا میں اپنے بھائی پر احسان کرنے میں موسیٰ علیہ السلام سے بڑا کوئی محسن نہیں ہے کیونکہ آپ نے اپنے بھائی ہارون علیہ السلام کے حق میں اللہ تعالیٰ سے نبی اور رسول بنانے کی سفارش کی تاکہ وہ آپ کے ساتھ فرعون اور اس کی فوج کے پاس جانے میں ساتھ دیں۔ (ابن کثیر: ۳؍ ۳۷۵)\nموسیٰ علیہ السلام کا ہارون علیہ السلام پر بڑا احسان ہے۔وضاحت کیجئے.\nوَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ ٣٥\n(أنتما ومن اتبعكما الغالبون)تم اور تمہارے متبعین غالب رہوگے۔ یہ وعدہ اس وقت موسیٰ علیہ السلام سے کیا گیا تھا جبکہ آپ بالکل تنہا تھے اور پردیس رہنے کے بعد اپنے وطن واپس لوٹ رہے تھے۔حالات وواقعات بدلتے رہے یہاں تک کہ اللہ تعالیٰ نے اپنا وعدہ پورا کردیا اور آپ کو پورے ملک اور بندوں پر اختیار عطاکردیا اور آپ اور آپ کے پیروکار ملک میں غالب آگئے۔ (السعدی؍ ۶۱۵)\nفرعون کے پاس موسیٰ علیہ السلام کو بھیجنے سے پہلے یہ آیت کس چیزکا فائدہ دیتی ہے؟\nقَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ ٣٥\nقصہ کے اس حصہ میں عبرت کا مقام یہ ہے کہ اس میں اس بات سے آگاہ کیاگیاہے کہ رسالت دراصل اللہ تعالیٰ کی طرف سے اس کے چنندہ بندوں پر خاص فیض ہوتا ہے۔ اور محمد صلی اللہ علیہ وسلم کی رسالت بالکل موسیٰ علیہ السلام کی رسالت کی طرح اچانک ملی تھی۔چنانچہ محمد صلی اللہ علیہ وسلم کو غار حرامیں بالکل اسی طرح ندادی گئی جیسے موسیٰ علیہ السلام کو جبل ِطورپر ندا دی گئی۔اس وقت آپ صلی اللہ علیہ وسلم کو اسی طرح خوف لاحق ہوا جس طرح موسیٰ علیہ السلام کو ہوا تھا اور پھر اللہ تعالیٰ نے آپ کو بالکل اسی طرح ثابت قدم کردیا جس طرح موسیٰ علیہ السلام کو ثابت قدم کردیا تھا اور یہ کہ اللہ تعالیٰ آپ صلی اللہ علیہ وسلم کے لئے دشمنوں کے مقابلہ میں کافی ہوگیا بالکل اسی طرح جس طرح موسیٰ علیہ السلام کے دشمنوں کے مقابلہ میں کافی ہوگیا۔ (ابن عاشور: ۲۰؍۱۱۸)\nآیت میں اس بات کی طرف اشارہ ہے کہ اللہ تعالیٰ اپنے نبی پاک محمد صلی اللہ علیہ وسلم کو ثابت قدم رکھے گا اور آپ کی ضرور مددفرمائیگا۔ اس کی وضاحت کیجئے.\nwords\nآنَسَديكھ ليا.\nجَذوَةٍآگ كا شعله.\nتَصطَلُونَتم گرمي حاصل كرو.\nشَاطِئِكناره /جانب.\nفَذَانِكَپس يه دو.\nرِدءًامددگار.\nسَنَشُدُّ عَضُدَكَهم آپ كو قوت ديں گے؛ آپ كي مدد كريں گے."]])